#ОСВ: 1000

observeEvent(input$dates1000, {
    start <- ymd(input$dates1000[[1]])
    end <- ymd(input$dates1000[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1000", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1000[[1]]
      r$end <- input$dates1000[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1000",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({
    if (!any(is.na(input$dates1000))) {
      from=as.Date(input$dates1000[1L])
      to=as.Date(input$dates1000[2L])
      if (from>to) to = from
      selectdates1010_1 <- seq.Date(from=from,
                               to=to, by = "day")
     data$df1010_1 <- data$df1010[as.Date(data$df1010$`Дата операции`) %in% selectdates1010_1, ]
    } else {
      selectdates1010_2 <- unique(as.Date(data$df1010$`Дата операции`))
