observeEvent(input$dates1121, {
    start <- ymd(input$dates1121[[1]])
    end <- ymd(input$dates1121[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1121", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1121[[1]]
      r$end <- input$dates1121[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1121",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

