observe({ if (!is.null(input$table1131_1Item1)) {
    data$df1131.1 <- hot_to_r(input$table1131_1Item1) 

    if (!any(is.na(input$dates1131_1)) && input$choices1131_1 == "Выбор по дате") {
     	from=as.Date(input$dates1131_1[1L])
      	to=as.Date(input$dates1131_1[2L])
      	if (from>to) to = from
      	selectdates1131_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1131.1_2 <- data$df1131.1[as.Date(data$df1131.1$"Дата операции") %in% selectdates1131_1_1, ]
    } else if (!is.null(input$text) && input$choices1131_1 == "Выбор по учетному номеру") {
      	data$df1131.1_2 <- data$df1131.1[data$df1131.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices1131_1 == "Выбор вида ценной бумаги") {
      	data$df1131.1_2 <- data$df1131.1[data$df1131.1$"Вид ценной бумаги" == input$text, ]
    } else if (!is.null(input$dates1131_1) && !any(is.na(input$dates1131_1)) && !is.null(input$text) && input$choices1131_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates1131_1[1L])
      	to=as.Date(input$dates1131_1[2L])
      	if (from>to) to = from
      	selectdates1131_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1131.1_2 <- data$df1131.1[as.Date(data$df1131.1$"Дата операции") %in% selectdates1131_1_2 & data$df1131.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1131_1) && !any(is.na(input$dates1131_1)) && !is.null(input$text) && input$choices1131_1 == "Выбор по дате и виду ценной бумаги") {
