observeEvent(input$dates1132_1, {
    start <- ymd(input$dates1132_1[[1]])
    end <- ymd(input$dates1132_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1132_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1132_1[[1]]
      r$end <- input$dates1132_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1132_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table1132_1Item1)) {
    data$df1132.1 <- hot_to_r(input$table1132_1Item1) 

    if (!any(is.na(input$dates1132_1)) && input$choices1132_1 == "Выбор по дате") {
     	from=as.Date(input$dates1132_1[1L])
      	to=as.Date(input$dates1132_1[2L])
      	if (from>to) to = from
      	selectdates1132_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1132.1_2 <- data$df1132.1[as.Date(data$df1132.1$"Дата операции") %in% selectdates1132_1_1, ]
    } else if (!is.null(input$text) && input$choices1132_1 == "Выбор по учетному номеру") {
      	data$df1132.1_2 <- data$df1132.1[data$df1132.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1132_1) && !any(is.na(input$dates1132_1)) && !is.null(input$text) && input$choices1132_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates1132_1[1L])
      	to=as.Date(input$dates1132_1[2L])
      	if (from>to) to = from
      	selectdates1132_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1132.1_2 <- data$df1132.1[as.Date(data$df1132.1$"Дата операции") %in% selectdates1132_1_2 & data$df1132.1$"Учетный номер" == input$text, ]
    } else {
        selectdates1132_1_3 <- unique(data$df1132.1$"Дата операции")
        data$df1132.1_2 <- data$df1132.1[data$df1132.1$"Дата операции" %in% selectdates1132_1_3, ]
    }
}
})  

  output$table1132_1Item1 <- renderRHandsontable({
    
   data$df1132.1[, `Сальдо конечное` := ifelse(!is.na(data$df1132.1[[8]]) & data$df1132.1[[8]] != 0,
							data$df1132.1[[8]], data$df1132.1[[6]] + data$df1132.1[[9]] - data$df1132.1[[10]])]

    rhandsontable(data$df1132.1, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
