observeEvent(input$dates1144, {
    start <- ymd(input$dates1144[[1]])
    end <- ymd(input$dates1144[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1144", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1144[[1]]
      r$end <- input$dates1144[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1144",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

observe({
    if (!any(is.na(input$dates1144))) {
      from=as.Date(input$dates1144[1L])
      to=as.Date(input$dates1144[2L])
      if (from>to) to = from
      selectdates1144_1_1 <- seq.Date(from=from,
                               to=to, by = "day")
     data$df1144.1_1 <- data$df1144.1[as.Date(data$df1144.1$`Дата операции`) %in% selectdates1144_1_1, ]
    } else {
      selectdates1144_1_2 <- unique(as.Date(data$df1144.1$`Дата операции`))
      data$df1144.1_1 <- data$df1144.1[data$df1144.1$`Дата операции` %in% selectdates1144_1_2, ]
    }
  })

  observe({
    if(!is.null(input$table1144_1Item1) && !any(is.na(input$table1144_1Item1)))
      data$df1144.1_1 <- hot_to_r(input$table1144_1Item1)
  })

