    start <- ymd(input$dates1147_1[[1]])
    end <- ymd(input$dates1147_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1147_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1147_1[[1]]
      r$end <- input$dates1147_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1147_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table1147_1Item1)) {
    data$df1147.1 <- hot_to_r(input$table1147_1Item1) 

    if (!any(is.na(input$dates1147_1)) && input$choices1147_1 == "Выбор по дате") {
     	from=as.Date(input$dates1147_1[1L])
      	to=as.Date(input$dates1147_1[2L])
      	if (from>to) to = from
      	selectdates1147_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1147.1_2 <- data$df1147.1[as.Date(data$df1147.1$"Дата операции") %in% selectdates1147_1_1, ]
    } else if (!is.null(input$text) && input$choices1147_1 == "Выбор по учетному номеру") {
      	data$df1147.1_2 <- data$df1147.1[data$df1147.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices1147_1 == "Выбор вида производной ценной бумаги") {
      	data$df1147.1_2 <- data$df1147.1[data$df1147.1$"Вид производной ценной бумаги" == input$text, ]
    } else if (!is.null(input$dates1147_1) && !any(is.na(input$dates1147_1)) && !is.null(input$text) && input$choices1147_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates1147_1[1L])
      	to=as.Date(input$dates1147_1[2L])
      	if (from>to) to = from
      	selectdates1147_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1147.1_2 <- data$df1147.1[as.Date(data$df1147.1$"Дата операции") %in% selectdates1147_1_2 & data$df1147.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1147_1) && !any(is.na(input$dates1147_1)) && !is.null(input$text) && input$choices1147_1 == "Выбор по дате и виду производной ценной бумаги") {
     	from=as.Date(input$dates1147_1[1L])
      	to=as.Date(input$dates1147_1[2L])
      	if (from>to) to = from
      	selectdates1147_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df1147.1_2 <- data$df1147.1[as.Date(data$df1147.1$"Дата операции") %in% selectdates1147_1_3 & data$df1147.1$"Вид производной ценной бумаги" == input$text, ]
    } else {
        selectdates1147_1_4 <- unique(data$df1147.1$"Дата операции")
        data$df1147.1_2 <- data$df1147.1[data$df1147.1$"Дата операции" %in% selectdates1147_1_4, ]
    }
}
})  

  output$table1147_1Item1 <- renderRHandsontable({
    
   data$df1147.1[, `Сальдо конечное` := ifelse(!is.na(data$df1147.1[[8]]) & data$df1147.1[[8]] != 0,
							data$df1147.1[[8]], data$df1147.1[[6]] + data$df1147.1[[9]] - data$df1147.1[[10]])]

    rhandsontable(data$df1147.1, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui1147_1 <- renderUI({
    if (input$choices1147_1 == "Выбор по дате") {
      	dateRangeInput("dates1147_1", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices1147_1 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите учетный номер:")
    } else if (input$choices1147_1 == "Выбор вида производной ценной бумаги") {
      	textInput("text", "Укажите вид производной ценной бумаги:")
    } else if (input$choices1147_1 == "Выбор по дате и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates1147_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите учетный номер:")
      )
    } else if (input$choices1147_1 == "Выбор по дате и виду производной ценной бумаги") {
      fluidRow(
       	dateRangeInput("dates1147_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите вид производной ценной бумаги:")
      )
    }
  })

  output$table1147_1Item2 <- renderRHandsontable({
    rhandsontable(data$df1147.1_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df1147.1 <- downloadHandler(
    filename = function() { "df1147.1.xlsx" },
