observeEvent(input$dates1151, {
    start <- ymd(input$dates1151[[1]])
    end <- ymd(input$dates1151[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1151", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1151[[1]]
      r$end <- input$dates1151[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1151",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table1151Item1)) {
    data$df1151 <- hot_to_r(input$table1151Item1) 

    if (!any(is.na(input$dates1151)) && input$choices1151 == "Выбор по дате") {
     	from=as.Date(input$dates1151[1L])
      	to=as.Date(input$dates1151[2L])
      	if (from>to) to = from
      	selectdates1151_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1151_2 <- data$df1151[as.Date(data$df1151$"Дата операции") %in% selectdates1151_1, ]
    } else if (!is.null(input$text) && input$choices1151 == "Выбор по учетному номеру") {
      	data$df1151_2 <- data$df1151[data$df1151$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1151) && !any(is.na(input$dates1151)) && !is.null(input$text) && input$choices1151 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates1151[1L])
      	to=as.Date(input$dates1151[2L])
      	if (from>to) to = from
      	selectdates1151_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1151_2 <- data$df1151[as.Date(data$df1151$"Дата операции") %in% selectdates1151_2 & data$df1151$"Учетный номер" == input$text, ]
    } else {
        selectdates1151_4 <- unique(data$df1151$"Дата операции")
        data$df1151_2 <- data$df1151[data$df1151$"Дата операции" %in% selectdates1151_4, ]
    }
}
