    if (!any(is.na(input$dates1162)) && input$choices1162 == "Выбор по дате") {
     	from=as.Date(input$dates1162[1L])
      	to=as.Date(input$dates1162[2L])
      	if (from>to) to = from
      	selectdates1162_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1162_2 <- data$df1162[as.Date(data$df1162$"Дата операции") %in% selectdates1162_1, ]
    } else if (!is.null(input$text) && input$choices1162 == "Выбор по учетному номеру") {
      	data$df1162_2 <- data$df1162[data$df1162$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1162) && !any(is.na(input$dates1162)) && !is.null(input$text) && input$choices1162 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates1162[1L])
      	to=as.Date(input$dates1162[2L])
      	if (from>to) to = from
      	selectdates1162_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1162_2 <- data$df1162[as.Date(data$df1162$"Дата операции") %in% selectdates1162_2 & data$df1162$"Учетный номер" == input$text, ]
    } else {
        selectdates1162_3 <- unique(data$df1162$"Дата операции")
        data$df1162_2 <- data$df1162[data$df1162$"Дата операции" %in% selectdates1162_3, ]
    }
}
})  

  output$table1162Item1 <- renderRHandsontable({
    
   data$df1162[, `Сальдо конечное` := ifelse(!is.na(data$df1162[[8]]) & data$df1162[[8]] != 0,
							data$df1162[[8]], data$df1162[[6]] + data$df1162[[9]] - data$df1162[[10]])]

