#1170

observeEvent(input$dates1170, {
    start <- ymd(input$dates1170[[1]])
    end <- ymd(input$dates1170[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1170", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1170[[1]]
      r$end <- input$dates1170[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1170",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table1170Item1) && !any(is.na(input$dates1170))) {
    data$df1170 <- hot_to_r(input$table1170Item1) 

    if (!any(is.na(input$dates1170)) && input$choices1170 == "Выбор по дате операции") {
     	from=as.Date(input$dates1170[1L])
      	to=as.Date(input$dates1170[2L])
      	if (from>to) to = from
      	selectdates1170_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1170_2 <- data$df1170[as.Date(data$df1170$"Дата операции") %in% selectdates1170_1, ]
    } else if (!is.null(input$text) && input$choices1170 == "Выбор по учетному номеру") {
      	data$df1170_2 <- data$df1170[data$df1170$"Учетный номер" == input$text, ]
    } else if (!is.null(input$sub_choice1170) && input$choices1170 == "Выбор группы финансовых активов") {
      	data$df1170_2 <- data$df1170[data$df1170$"Группа финансовых активов" == input$sub_choice1170, ]
    } else if (!is.null(input$dates1170) && !any(is.na(input$dates1170)) && !is.null(input$text) && input$choices1170 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates1170[1L])
      	to=as.Date(input$dates1170[2L])
      	if (from>to) to = from
      	selectdates1170_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1170_2 <- data$df1170[as.Date(data$df1170$"Дата операции") %in% selectdates1170_2 & data$df1170$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1170) && !any(is.na(input$dates1170)) && !is.null(input$sub_choice1170) && input$choices1170 == "Выбор по дате операции и группе финансовых активов") {
     	from=as.Date(input$dates1170[1L])
      	to=as.Date(input$dates1170[2L])
      	if (from>to) to = from
      	selectdates1170_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df1170_2 <- data$df1170[as.Date(data$df1170$"Дата операции") %in% selectdates1170_3 & data$df1170$"Группа финансовых активов" == input$sub_choice1170, ]
    } else {
        selectdates1170_4 <- unique(data$df1170$"Дата операции")
        data$df1170_2 <- data$df1170[data$df1170$"Дата операции" %in% selectdates1170_4, ]
    }
}
})  

