     	from=as.Date(input$dates1510[1L])
      	to=as.Date(input$dates1510[2L])
      	if (from>to) to = from
      	selectdates1510_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1510_2 <- data$df1510[as.Date(data$df1510$"Дата операции") %in% selectdates1510_1, ]
    } else if (!is.null(input$text) && input$choices1510 == "Выбор по учетному номеру") {
      	data$df1510_2 <- data$df1510[data$df1510$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices1510 == "Выбор вида (названия) долгосрочного актива") {
      	data$df1510_2 <- data$df1510[data$df1510$"Вид (название) долгосрочного актива" == input$text, ]
    } else if (!is.null(input$dates1510) && !any(is.na(input$dates1510)) && !is.null(input$text) && input$choices1510 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates1510[1L])
      	to=as.Date(input$dates1510[2L])
      	if (from>to) to = from
      	selectdates1510_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1510_2 <- data$df1510[as.Date(data$df1510$"Дата операции") %in% selectdates1510_2 & data$df1510$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1510) && !any(is.na(input$dates1510)) && !is.null(input$text) && input$choices1510 == "Выбор по дате операции и виду (названию) долгосрочного актива") {
     	from=as.Date(input$dates1510[1L])
