observeEvent(input$dates1711, {
    start <- ymd(input$dates1711[[1]])
    end <- ymd(input$dates1711[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1711", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1711[[1]]
      r$end <- input$dates1711[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1711",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table1711Item1)) {
    data$df1711 <- hot_to_r(input$table1711Item1) 

    if (!any(is.na(input$dates1711)) && input$choices1711 == "Выбор по дате операции") {
     	from=as.Date(input$dates1711[1L])
      	to=as.Date(input$dates1711[2L])
      	if (from>to) to = from
      	selectdates1711_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1711_2 <- data$df1711[as.Date(data$df1711$"Дата операции") %in% selectdates1711_1, ]
    } else if (!is.null(input$text) && input$choices1711 == "Выбор по учетному номеру") {
      	data$df1711_2 <- data$df1711[data$df1711$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1711) && !any(is.na(input$dates1711)) && !is.null(input$text) && input$choices1711 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates1711[1L])
      	to=as.Date(input$dates1711[2L])
      	if (from>to) to = from
      	selectdates1711_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1711_2 <- data$df1711[as.Date(data$df1711$"Дата операции") %in% selectdates1711_2 & data$df1711$"Учетный номер" == input$text, ]
    } else {
        selectdates1711_3 <- unique(data$df1711$"Дата операции")
        data$df1711_2 <- data$df1711[data$df1711$"Дата операции" %in% selectdates1711_3, ]
    }
}
})  

  output$table1711Item1 <- renderRHandsontable({
    
   data$df1711[, `Сальдо конечное` := data$df1711[[5]] + data$df1711[[6]] - data$df1711[[7]]]

    rhandsontable(data$df1711, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui1711 <- renderUI({
    if (input$choices1711 == "Выбор по дате операции") {
      	dateRangeInput("dates1711", "Выберите период времени:", format="yyyy-mm-dd",
