    end <- ymd(input$dates1714[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1714", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1714[[1]]
      r$end <- input$dates1714[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1714",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table1714Item1)) {
    data$df1714 <- hot_to_r(input$table1714Item1) 

    if (!any(is.na(input$dates1714)) && input$choices1714 == "Выбор по дате операции") {
     	from=as.Date(input$dates1714[1L])
      	to=as.Date(input$dates1714[2L])
      	if (from>to) to = from
      	selectdates1714_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1714_2 <- data$df1714[as.Date(data$df1714$"Дата операции") %in% selectdates1714_1, ]
    } else if (!is.null(input$text) && input$choices1714 == "Выбор по учетному номеру") {
      	data$df1714_2 <- data$df1714[data$df1714$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1714) && !any(is.na(input$dates1714)) && !is.null(input$text) && input$choices1714 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates1714[1L])
      	to=as.Date(input$dates1714[2L])
      	if (from>to) to = from
      	selectdates1714_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1714_2 <- data$df1714[as.Date(data$df1714$"Дата операции") %in% selectdates1714_2 & data$df1714$"Учетный номер" == input$text, ]
    } else {
        selectdates1714_3 <- unique(data$df1714$"Дата операции")
        data$df1714_2 <- data$df1714[data$df1714$"Дата операции" %in% selectdates1714_3, ]
    }
}
})  

  output$table1714Item1 <- renderRHandsontable({
    
   data$df1714[, `Сальдо конечное` := data$df1714[[6]] + data$df1714[[7]] - data$df1714[[9]]]

    rhandsontable(data$df1714, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui1714 <- renderUI({
    if (input$choices1714 == "Выбор по дате операции") {
      	dateRangeInput("dates1714", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices1714 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите учетный номер:")
    } else if (input$choices1714 == "Выбор по дате и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates1714", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите учетный номер:")
      )
    } 
  })

  output$table1714Item2 <- renderRHandsontable({
    rhandsontable(data$df1714_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df1714 <- downloadHandler(
    filename = function() { "df1714.xlsx" },
    content = function(file) {
      write.xlsx(data$df1714, file)
    }
  )

  output$download_df1714_2 <- downloadHandler(
    filename = function() { "df1714_2.xlsx" },
    content = function(file) {
      write.xlsx(data$df1714_2, file)
    }
  )

