#2021.1

observeEvent(input$dates2021_1, {
    start <- ymd(input$dates2021_1[[1]])
    end <- ymd(input$dates2021_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2021_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2021_1[[1]]
      r$end <- input$dates2021_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2021_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2021_1Item1)) {
    data$df2021.1 <- hot_to_r(input$table2021_1Item1) 

    if (!any(is.na(input$dates2021_1)) && input$choices2021_1 == "Выбор по дате") {
     	from=as.Date(input$dates2021_1[1L])
      	to=as.Date(input$dates2021_1[2L])
      	if (from>to) to = from
      	selectdates2021_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2021.1_2 <- data$df2021.1[as.Date(data$df2021.1$"Дата операции") %in% selectdates2021_1_1, ]
    } else if (!is.null(input$text) && input$choices2021_1 == "Выбор по учетному номеру") {
      	data$df2021.1_2 <- data$df2021.1[data$df2021.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2021_1 == "Выбор вида долевого инструмента") {
      	data$df2021.1_2 <- data$df2021.1[data$df2021.1$"Вид долевого инструмента" == input$text, ]
    } else if (!is.null(input$dates2021_1) && !any(is.na(input$dates2021_1)) && !is.null(input$text) && input$choices2021_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates2021_1[1L])
      	to=as.Date(input$dates2021_1[2L])
      	if (from>to) to = from
      	selectdates2021_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2021.1_2 <- data$df2021.1[as.Date(data$df2021.1$"Дата операции") %in% selectdates2021_1_2 & data$df2021.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2021_1) && !any(is.na(input$dates2021_1)) && !is.null(input$text) && input$choices2021_1 == "Выбор по дате и виду долевого инструмента") {
     	from=as.Date(input$dates2021_1[1L])
      	to=as.Date(input$dates2021_1[2L])
      	if (from>to) to = from
      	selectdates2021_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2021.1_2 <- data$df2021.1[as.Date(data$df2021.1$"Дата операции") %in% selectdates2021_1_3 & data$df2021.1$"Вид долевого инструмента" == input$text, ]
    } else {
        selectdates2021_1_4 <- unique(data$df2021.1$"Дата операции")
        data$df2021.1_2 <- data$df2021.1[data$df2021.1$"Дата операции" %in% selectdates2021_1_4, ]
    }
}
})  

  output$table2021_1Item1 <- renderRHandsontable({
    
   data$df2021.1[, `Сальдо конечное` := ifelse(!is.na(data$df2021.1[[10]]) & data$df2021.1[[10]] != 0,
							data$df2021.1[[10]], data$df2021.1[[7]] + data$df2021.1[[12]]-data$df2021.1[[14]])]

    rhandsontable(data$df2021.1, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui2021_1 <- renderUI({
    if (input$choices2021_1 == "Выбор по дате") {
      	dateRangeInput("dates2021_1", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2021_1 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите учетный номер:")
    } else if (input$choices2021_1 == "Выбор вида долевого инструмента") {
      	textInput("text", "Укажите вид долевого инструмента:")
    } else if (input$choices2021_1 == "Выбор по дате и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2021_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите учетный номер:")
      )
    } else if (input$choices2021_1 == "Выбор по дате и виду долевого инструмента") {
      fluidRow(
       	dateRangeInput("dates2021_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите вид долевого инструмента:")
      )
    }
  })

  output$table2021_1Item2 <- renderRHandsontable({
    rhandsontable(data$df2021.1_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df2021.1 <- downloadHandler(
    filename = function() { "df2021.1.xlsx" },
    content = function(file) {
      write.xlsx(data$df2021.1, file)
    }
  )

