     	from=as.Date(input$dates2031_1[1L])
      	to=as.Date(input$dates2031_1[2L])
      	if (from>to) to = from
      	selectdates2031_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2031.1_2 <- data$df2031.1[as.Date(data$df2031.1$"Дата операции") %in% selectdates2031_1_1, ]
    } else if (!is.null(input$text) && input$choices2031_1 == "Выбор по учетному номеру") {
      	data$df2031.1_2 <- data$df2031.1[data$df2031.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2031_1 == "Выбор вида ценной бумаги") {
      	data$df2031.1_2 <- data$df2031.1[data$df2031.1$"Вид ценной бумаги" == input$text, ]
    } else if (!is.null(input$dates2031_1) && !any(is.na(input$dates2031_1)) && !is.null(input$text) && input$choices2031_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates2031_1[1L])
      	to=as.Date(input$dates2031_1[2L])
      	if (from>to) to = from
      	selectdates2031_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2031.1_2 <- data$df2031.1[as.Date(data$df2031.1$"Дата операции") %in% selectdates2031_1_2 & data$df2031.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2031_1) && !any(is.na(input$dates2031_1)) && !is.null(input$text) && input$choices2031_1 == "Выбор по дате и виду ценной бумаги") {
     	from=as.Date(input$dates2031_1[1L])
      	to=as.Date(input$dates2031_1[2L])
