observeEvent(input$dates2035, {
    start <- ymd(input$dates2035[[1]])
    end <- ymd(input$dates2035[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2035", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2035[[1]]
      r$end <- input$dates2035[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2035",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

observe({
    if (!any(is.na(input$dates2035))) {
      from=as.Date(input$dates2035[1L])
      to=as.Date(input$dates2035[2L])
      if (from>to) to = from
      selectdates2035_1_1 <- seq.Date(from=from,
                               to=to, by = "day")
     data$df2035.1_1 <- data$df2035.1[as.Date(data$df2035.1$`Дата операции`) %in% selectdates2035_1_1, ]
    } else {
      selectdates2035_1_2 <- unique(as.Date(data$df2035.1$`Дата операции`))
      data$df2035.1_1 <- data$df2035.1[data$df2035.1$`Дата операции` %in% selectdates2035_1_2, ]
    }
  })

  observe({
    if(!is.null(input$table2035_1Item1) && !any(is.na(input$table2035_1Item1)))
      data$df2035.1_1<- hot_to_r(input$table2035_1Item1)
  })

