#2035.1

observeEvent(input$dates2035_1, {
    start <- ymd(input$dates2035_1[[1]])
    end <- ymd(input$dates2035_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2035_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2035_1[[1]]
      r$end <- input$dates2035_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2035_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2035_1Item1)) {
    data$df2035.1 <- hot_to_r(input$table2035_1Item1) 

    if (!any(is.na(input$dates2035_1)) && input$choices2035_1 == "Выбор по дате") {
     	from=as.Date(input$dates2035_1[1L])
      	to=as.Date(input$dates2035_1[2L])
      	if (from>to) to = from
      	selectdates2035_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2035.1_2 <- data$df2035.1[as.Date(data$df2035.1$"Дата операции") %in% selectdates2035_1_1, ]
    } else if (!is.null(input$text) && input$choices2035_1 == "Выбор по учетному номеру") {
      	data$df2035.1_2 <- data$df2035.1[data$df2035.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2035_1) && !any(is.na(input$dates2035_1)) && !is.null(input$text) && input$choices2035_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates2035_1[1L])
      	to=as.Date(input$dates2035_1[2L])
      	if (from>to) to = from
      	selectdates2035_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2035.1_2 <- data$df2035.1[as.Date(data$df2035.1$"Дата операции") %in% selectdates2035_1_2 & data$df2035.1$"Учетный номер" == input$text, ]
    } else {
        selectdates2035_1_3 <- unique(data$df2035.1$"Дата операции")
        data$df2035.1_2 <- data$df2035.1[data$df2035.1$"Дата операции" %in% selectdates2035_1_3, ]
    }
}
})  

  output$table2035_1Item1 <- renderRHandsontable({
    
   data$df2035.1[, `Сальдо конечное` := ifelse(!is.na(data$df2035.1[[8]]) & data$df2035.1[[8]] != 0,
							data$df2035.1[[8]], data$df2035.1[[6]] + data$df2035.1[[9]] - data$df2035.1[[10]])]

    rhandsontable(data$df2035.1, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui2035_1 <- renderUI({
    if (input$choices2035_1 == "Выбор по дате") {
      	dateRangeInput("dates2035_1", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2035_1 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите учетный номер:")
    } else if (input$choices2035_1 == "Выбор по дате и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2035_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите учетный номер:")
      )
    } 
  })

  output$table2035_1Item2 <- renderRHandsontable({
    rhandsontable(data$df2035.1_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df2035.1 <- downloadHandler(
    filename = function() { "df2035.1.xlsx" },
    content = function(file) {
      write.xlsx(data$df2035.1, file)
    }
  )

  output$download_df2035.1_2 <- downloadHandler(
    filename = function() { "df2035.1_2.xlsx" },
    content = function(file) {
      write.xlsx(data$df2035.1_2, file)
    }
  )

