#2051

observeEvent(input$dates2051, {
    start <- ymd(input$dates2051[[1]])
    end <- ymd(input$dates2051[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2051", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2051[[1]]
      r$end <- input$dates2051[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2051",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2051Item1)) {
    data$df2051 <- hot_to_r(input$table2051Item1) 

    if (!any(is.na(input$dates2051)) && input$choices2051 == "Выбор по дате") {
     	from=as.Date(input$dates2051[1L])
      	to=as.Date(input$dates2051[2L])
      	if (from>to) to = from
      	selectdates2051_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2051_2 <- data$df2051[as.Date(data$df2051$"Дата операции") %in% selectdates2051_2, ]
    } else if (!is.null(input$text) && input$choices2051 == "Выбор по учетному номеру") {
      	data$df2051_2 <- data$df2051[data$df2051$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2051) && !any(is.na(input$dates2051)) && !is.null(input$text) && input$choices2051 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates2051[1L])
      	to=as.Date(input$dates2051[2L])
      	if (from>to) to = from
      	selectdates2051_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2051_2 <- data$df2051[as.Date(data$df2051$"Дата операции") %in% selectdates2051_2 & data$df2051$"Учетный номер" == input$text, ]
    } else {
        selectdates2051_4 <- unique(data$df2051$"Дата операции")
        data$df2051_2 <- data$df2051[data$df2051$"Дата операции" %in% selectdates2051_4, ]
    }
}
})  

  output$table2051Item1 <- renderRHandsontable({
    
   data$df2051[, `Сальдо конечное` := ifelse(!is.na(data$df2051[[9]]) & data$df2051[[9]] != 0,
							data$df2051[[9]], data$df2051[[7]] + data$df2051[[10]] - data$df2051[[11]]
  )]

    rhandsontable(data$df2051, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui2051 <- renderUI({
    if (input$choices2051 == "Выбор по дате") {
      	dateRangeInput("dates2051", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2051 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите учетный номер:")
    } else if (input$choices2051 == "Выбор по дате и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2051", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите учетный номер:")
      )
    } 
  })

