    rhandsontable(data$df2051_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df2051 <- downloadHandler(
