observeEvent(input$dates2080, {
    start <- ymd(input$dates2080[[1]])
    end <- ymd(input$dates2080[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2080", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2080[[1]]
      r$end <- input$dates2080[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2080",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2080Item1) && !any(is.na(input$dates2080))) {
    data$df2080 <- hot_to_r(input$table2080Item1) 

    if (!any(is.na(input$dates2080)) && input$choices2080 == "Выбор по дате операции") {
     	from=as.Date(input$dates2080[1L])
      	to=as.Date(input$dates2080[2L])
      	if (from>to) to = from
      	selectdates2080_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2080_2 <- data$df2080[as.Date(data$df2080$"Дата операции") %in% selectdates2080_1, ]
    } else if (!is.null(input$text) && input$choices2080 == "Выбор по учетному номеру") {
      	data$df2080_2 <- data$df2080[data$df2080$"Учетный номер" == input$text, ]
    } else if (!is.null(input$sub_choice2080) && input$choices2080 == "Выбор группы финансовых активов") {
      	data$df2080_2 <- data$df2080[data$df2080$"Группа финансовых активов" == input$sub_choice2080, ]
    } else if (!is.null(input$dates2080) && !any(is.na(input$dates2080)) && !is.null(input$text) && input$choices2080 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2080[1L])
      	to=as.Date(input$dates2080[2L])
      	if (from>to) to = from
      	selectdates2080_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2080_2 <- data$df2080[as.Date(data$df2080$"Дата операции") %in% selectdates2080_2 & data$df2080$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2080) && !any(is.na(input$dates2080)) && !is.null(input$sub_choice2080) && input$choices2080 == "Выбор по дате операции и группе финансовых активов") {
     	from=as.Date(input$dates2080[1L])
      	to=as.Date(input$dates2080[2L])
      	if (from>to) to = from
      	selectdates2080_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2080_2 <- data$df2080[as.Date(data$df2080$"Дата операции") %in% selectdates2080_3 & data$df2080$"Группа финансовых активов" == input$sub_choice2080, ]
    } else {
        selectdates2080_4 <- unique(data$df2080$"Дата операции")
        data$df2080_2 <- data$df2080[data$df2080$"Дата операции" %in% selectdates2080_4, ]
    }
}
})  

