#2311

observeEvent(input$dates2311, {
    start <- ymd(input$dates2311[[1]])
    end <- ymd(input$dates2311[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2311", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2311[[1]]
      r$end <- input$dates2311[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2311",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2311Item1) && !any(is.na(input$dates2311))) {
    data$df2311 <- hot_to_r(input$table2311Item1) 

    if (!any(is.na(input$dates2311)) && input$choices2311 == "Выбор по дате операции") {
     	from=as.Date(input$dates2311[1L])
      	to=as.Date(input$dates2311[2L])
      	if (from>to) to = from
      	selectdates2311_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2311_2 <- data$df2311[as.Date(data$df2311$"Дата операции") %in% selectdates2311_1, ]
    } else if (!is.null(input$text) && input$choices2311 == "Выбор по кадастровому или иному учетному номеру инвестиционного имущества") {
      	data$df2311_2 <- data$df2311[data$df2311$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2311) && !any(is.na(input$dates2311)) && !is.null(input$text) && input$choices2311 == "Выбор по дате операции и кадастровому или иному учетному номеру инвестиционного имущества") {
     	from=as.Date(input$dates2311[1L])
      	to=as.Date(input$dates2311[2L])
      	if (from>to) to = from
      	selectdates2311_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2311_2 <- data$df2311[as.Date(data$df2311$"Дата операции") %in% selectdates2311_3 & data$df2311$"Учетный номер" == input$text, ]
    } else {
        selectdates2311_4 <- unique(data$df2311$"Дата операции")
        data$df2311_2 <- data$df2311[data$df2311$"Дата операции" %in% selectdates2311_4, ]
    }
}
})  

