      	if (from>to) to = from
      	selectdates2330_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2330_2 <- data$df2330[as.Date(data$df2330$"Дата операции") %in% selectdates2330_1, ]
    } else if (!is.null(input$text) && input$choices2330 == "Выбор по учетному номеру") {
      	data$df2330_2 <- data$df2330[data$df2330$"Учетный номер" == input$text, ]
    } else if (!is.null(input$sub_choice2330) && input$choices2330 == "Выбор группы инвестиционного имущества") {
      	data$df2330_2 <- data$df2330[data$df2330$"Группа инвестиционного имущества" == input$sub_choice2330, ]
    } else if (!is.null(input$dates2330) && !any(is.na(input$dates2330)) && !is.null(input$text) && input$choices2330 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2330[1L])
      	to=as.Date(input$dates2330[2L])
      	if (from>to) to = from
      	selectdates2330_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2330_2 <- data$df2330[as.Date(data$df2330$"Дата операции") %in% selectdates2330_2 & data$df2330$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2330) && !any(is.na(input$dates2330)) && !is.null(input$sub_choice2330) && input$choices2330 == "Выбор по дате операции и группе инвестиционного имущества") {
     	from=as.Date(input$dates2330[1L])
      	to=as.Date(input$dates2330[2L])
      	if (from>to) to = from
      	selectdates2330_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2330_2 <- data$df2330[as.Date(data$df2330$"Дата операции") %in% selectdates2330_3 & data$df2330$"Группа инвестиционного имущества" == input$sub_choice2330, ]
    } else {
        selectdates2330_4 <- unique(data$df2330$"Дата операции")
