      	selectdates2413_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2413_2 <- data$df2413[as.Date(data$df2413$"Дата операции") %in% selectdates2413_2 & data$df2413$"Учетный номер" == input$text, ]
