#2421

observeEvent(input$dates2421, {
    start <- ymd(input$dates2421[[1]])
    end <- ymd(input$dates2421[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2421", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2421[[1]]
      r$end <- input$dates2421[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2421",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2421Item1) && !any(is.na(input$dates2421))) {
    data$df2421 <- hot_to_r(input$table2421Item1) 

    if (!any(is.na(input$dates2421)) && input$choices2421 == "Выбор по дате операции") {
     	from=as.Date(input$dates2421[1L])
      	to=as.Date(input$dates2421[2L])
      	if (from>to) to = from
      	selectdates2421_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2421_2 <- data$df2421[as.Date(data$df2421$"Дата операции") %in% selectdates2421_1, ]
    } else if (!is.null(input$text) && input$choices2421 == "Выбор по учетному номеру") {
      	data$df2421_2 <- data$df2421[data$df2421$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2421) && !any(is.na(input$dates2421)) && !is.null(input$text) && input$choices2421 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2421[1L])
      	to=as.Date(input$dates2421[2L])
      	if (from>to) to = from
      	selectdates2421_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2421_2 <- data$df2421[as.Date(data$df2421$"Дата операции") %in% selectdates2421_3 & data$df2421$"Учетный номер" == input$text, ]
    } else {
        selectdates2421_4 <- unique(data$df2421$"Дата операции")
        data$df2421_2 <- data$df2421[data$df2421$"Дата операции" %in% selectdates2421_4, ]
    }
}
})  

  output$table2421Item1 <- renderRHandsontable({

   data$df2421[, `Сальдо конечное` := `Сальдо начальное` + `Кредит` - `Дебет`]

    rhandsontable(data$df2421, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui2421 <- renderUI({
    if (input$choices2421 == "Выбор по дате операции") {
      	dateRangeInput("dates2421", "Выберите период времени:",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2421 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите учетный номер:")
    } else if (input$choices2421 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2421", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите учетный номер:")
      )
    }
  })

  output$table2421Item2 <- renderRHandsontable({
    rhandsontable(data$df2421_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df2421 <- downloadHandler(
    filename = function() { "df2421.xlsx" },
    content = function(file) {
      write.xlsx(data$df2421, file)
    }
  )

  output$download_df2421_2 <- downloadHandler(
    filename = function() { "df2421_2.xlsx" },
    content = function(file) {
      write.xlsx(data$df2421_2, file)
    }
  )

