      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2441Item1) && !any(is.na(input$dates2441))) {
    data$df2441 <- hot_to_r(input$table2441Item1) 

    if (!any(is.na(input$dates2441)) && input$choices2441 == "Выбор по дате") {
     	from=as.Date(input$dates2441[1L])
      	to=as.Date(input$dates2441[2L])
      	if (from>to) to = from
      	selectdates2441_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2441_2 <- data$df2441[as.Date(data$df2441$"Дата операции") %in% selectdates2441_1, ]
    } else if (!is.null(input$text) && input$choices2441 == "Выбор по учетному номеру") {
      	data$df2441_2 <- data$df2441[data$df2441$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2441 == "Выбор кадастрового или инвентарьного номера земельного участка") {
      	data$df2441_2 <- data$df2441[data$df2441$"Кадастровый или инвентарьный номер земельного участка" == input$text, ]
    } else if (!is.null(input$dates2441) && !any(is.na(input$dates2441)) && !is.null(input$text) && input$choices2441 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates2441[1L])
      	to=as.Date(input$dates2441[2L])
      	if (from>to) to = from
      	selectdates2441_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2441_2 <- data$df2441[as.Date(data$df2441$"Дата операции") %in% selectdates2441_2 & data$df2441$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2441) && !any(is.na(input$dates2441)) && !is.null(input$text) && input$choices2441 == "Выбор по дате и кадастровому или инвентарьному номеру земельного участка") {
     	from=as.Date(input$dates2441[1L])
      	to=as.Date(input$dates2441[2L])
      	if (from>to) to = from
      	selectdates2441_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2441_2 <- data$df2441[as.Date(data$df2441$"Дата операции") %in% selectdates2441_3 & data$df2441$"Кадастровый или инвентарьный номер земельного участка" == input$text, ]
    } else {
        selectdates2441_4 <- unique(data$df2441$"Дата операции")
        data$df2441_2 <- data$df2441[data$df2441$"Дата операции" %in% selectdates2441_4, ]
    }
}
})  

