#2710

observeEvent(input$dates2710, {
    start <- ymd(input$dates2710[[1]])
    end <- ymd(input$dates2710[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2710", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2710[[1]]
      r$end <- input$dates2710[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2710",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table2710Item1) && !any(is.na(input$dates2710))) {
    data$df2710 <- hot_to_r(input$table2710Item1) 

    if (!any(is.na(input$dates2710)) && input$choices2710 == "Выбор по дате операции") {
     	from=as.Date(input$dates2710[1L])
      	to=as.Date(input$dates2710[2L])
      	if (from>to) to = from
      	selectdates2710_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2710_2 <- data$df2710[as.Date(data$df2710$"Дата операции") %in% selectdates2710_1, ]
    } else if (!is.null(input$text) && input$choices2710 == "Выбор по учетному номеру") {
      	data$df2710_2 <- data$df2710[data$df2710$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2710) && !any(is.na(input$dates2710)) && !is.null(input$text) && input$choices2710 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2710[1L])
      	to=as.Date(input$dates2710[2L])
      	if (from>to) to = from
      	selectdates2710_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2710_2 <- data$df2710[as.Date(data$df2710$"Дата операции") %in% selectdates2710_2 & data$df2710$"Учетный номер" == input$text, ]
    } else {
        selectdates2710_4 <- unique(data$df2710$"Дата операции")
        data$df2710_2 <- data$df2710[data$df2710$"Дата операции" %in% selectdates2710_4, ]
    }
}
})  

