      	data$df2750_2 <- data$df2750[as.Date(data$df2750$"Дата операции") %in% selectdates2750_2 & data$df2750$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2750) && !any(is.na(input$dates2750)) && !is.null(input$sub_choice2750) && input$choices2750 == "Выбор по дате операции и группе нематериальных активов") {
