observeEvent(input$dates3021_1, {
    start <- ymd(input$dates3021_1[[1]])
    end <- ymd(input$dates3021_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates3021_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates3021_1[[1]]
      r$end <- input$dates3021_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates3021_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table3021_1Item1)) {
    data$df3021.1 <- hot_to_r(input$table3021_1Item1) 

    if (!any(is.na(input$dates3021_1)) && input$choices3021_1 == "Выбор по дате") {
     	from=as.Date(input$dates3021_1[1L])
      	to=as.Date(input$dates3021_1[2L])
      	if (from>to) to = from
      	selectdates3021_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3021.1_2 <- data$df3021.1[as.Date(data$df3021.1$"Дата операции") %in% selectdates3021_1_1, ]
    } else if (!is.null(input$text) && input$choices3021_1 == "Выбор по учетному номеру") {
      	data$df3021.1_2 <- data$df3021.1[data$df3021.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices3021_1 == "Выбор вида ценной бумаги") {
      	data$df3021.1_2 <- data$df3021.1[data$df3021.1$"Вид ценной бумаги" == input$text, ]
    } else if (!is.null(input$dates3021_1) && !any(is.na(input$dates3021_1)) && !is.null(input$text) && input$choices3021_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates3021_1[1L])
      	to=as.Date(input$dates3021_1[2L])
      	if (from>to) to = from
      	selectdates3021_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3021.1_2 <- data$df3021.1[as.Date(data$df3021.1$"Дата операции") %in% selectdates3021_1_2 & data$df3021.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3021_1) && !any(is.na(input$dates3021_1)) && !is.null(input$text) && input$choices3021_1 == "Выбор по дате и виду ценной бумаги") {
     	from=as.Date(input$dates3021_1[1L])
      	to=as.Date(input$dates3021_1[2L])
      	if (from>to) to = from
      	selectdates3021_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df3021.1_2 <- data$df3021.1[as.Date(data$df3021.1$"Дата операции") %in% selectdates3021_1_3 & data$df3021.1$"Вид ценной бумаги" == input$text, ]
    } else {
        selectdates3021_1_4 <- unique(data$df3021.1$"Дата операции")
        data$df3021.1_2 <- data$df3021.1[data$df3021.1$"Дата операции" %in% selectdates3021_1_4, ]
    }
}
})

  output$table3021_1Item1 <- renderRHandsontable({
    
   data$df3021.1[, `Сальдо конечное` := ifelse(!is.na(data$df3021.1[[12]]) & data$df3021.1[[12]] != 0,
							data$df3021.1[[12]], data$df3021.1[[9]] + data$df3021.1[[14]]-data$df3021.1[[16]])]

