 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates3034_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates3034_1[[1]]
      r$end <- input$dates3034_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates3034_1",
