    } else if (!is.null(input$text) && input$choices3034_1 == "Выбор вида производной ценной бумаги") {
      	data$df3034.1_2 <- data$df3034.1[data$df3034.1$"Вид производной ценной бумаги" == input$text, ]
    } else if (!is.null(input$dates3034_1) && !any(is.na(input$dates3034_1)) && !is.null(input$text) && input$choices3034_1 == "Выбор по дате и учетному номеру") {
