      	if (from>to) to = from
      	selectdates3037_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3037.1_2 <- data$df3037.1[as.Date(data$df3037.1$"Дата операции") %in% selectdates3037_1_2 & data$df3037.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3037_1) && !any(is.na(input$dates3037_1)) && !is.null(input$text) && input$choices3037_1 == "Выбор по дате и виду производной ценной бумаги") {
     	from=as.Date(input$dates3037_1[1L])
      	to=as.Date(input$dates3037_1[2L])
