      	selectdates3037_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df3037.1_2 <- data$df3037.1[as.Date(data$df3037.1$"Дата операции") %in% selectdates3037_1_3 & data$df3037.1$"Вид производной ценной бумаги" == input$text, ]
