observeEvent(input$dates3041, {
    start <- ymd(input$dates3041[[1]])
    end <- ymd(input$dates3041[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates3041", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates3041[[1]]
      r$end <- input$dates3041[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates3041",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table3041Item1)) {
    data$df3041 <- hot_to_r(input$table3041Item1) 

    if (!any(is.na(input$dates3041)) && input$choices3041 == "Выбор по дате") {
     	from=as.Date(input$dates3041[1L])
      	to=as.Date(input$dates3041[2L])
      	if (from>to) to = from
      	selectdates3041_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3041_2 <- data$df3041[as.Date(data$df3041$"Дата операции") %in% selectdates3041_1, ]
    } else if (!is.null(input$text) && input$choices3041 == "Выбор по учетному номеру") {
      	data$df3041_2 <- data$df3041[data$df3041$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices3041 == "Выбор вида долевого участия") {
      	data$df3041_2 <- data$df3041[data$df3041$"Вид долевого участия" == input$text, ]
    } else if (!is.null(input$dates3041) && !any(is.na(input$dates3041)) && !is.null(input$text) && input$choices3041 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates3041[1L])
      	to=as.Date(input$dates3041[2L])
      	if (from>to) to = from
      	selectdates3041_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3041_2 <- data$df3041[as.Date(data$df3041$"Дата операции") %in% selectdates3041_2 & data$df3041$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3041) && !any(is.na(input$dates3041)) && !is.null(input$text) && input$choices3041 == "Выбор по дате и виду долевого участия") {
     	from=as.Date(input$dates3041[1L])
      	to=as.Date(input$dates3041[2L])
      	if (from>to) to = from
      	selectdates3041_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df3041_2 <- data$df3041[as.Date(data$df3041$"Дата операции") %in% selectdates3041_3 & data$df3041$"Вид долевого участия" == input$text, ]
    } else {
        selectdates3041_4 <- unique(data$df3041$"Дата операции")
        data$df3041_2 <- data$df3041[data$df3041$"Дата операции" %in% selectdates3041_4, ]
    }
}
})  

  output$table3041Item1 <- renderRHandsontable({
    
   data$df3041[, `Сальдо конечное` := ifelse(!is.na(data$df3041[[10]]) & data$df3041[[10]] != 0,
							data$df3041[[10]], data$df3041[[7]] + data$df3041[[12]] - data$df3041[[14]])]

    rhandsontable(data$df3041, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui3041 <- renderUI({
    if (input$choices3041 == "Выбор по дате") {
      	dateRangeInput("dates3041", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices3041 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите учетный номер:")
    } else if (input$choices3041 == "Выбор вида долевого участия") {
      	textInput("text", "Укажите вид долевого участия:")
    } else if (input$choices3041 == "Выбор по дате и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates3041", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите учетный номер:")
      )
    } else if (input$choices3041 == "Выбор по дате и виду долевого участия") {
      fluidRow(
       	dateRangeInput("dates3041", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите вид долевого участия:")
      )
    }
  })

  output$table3041Item2 <- renderRHandsontable({
    rhandsontable(data$df3041_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df3041 <- downloadHandler(
    filename = function() { "df3041.xlsx" },
    content = function(file) {
      write.xlsx(data$df3041, file)
    }
  )

  output$download_df3041_2 <- downloadHandler(
    filename = function() { "df3041_2.xlsx" },
    content = function(file) {
      write.xlsx(data$df3041_2, file)
    }
  )

