observe({ if (!is.null(input$table3061_1Item1)) {
    data$df3061.1 <- hot_to_r(input$table3061_1Item1) 

    if (!any(is.na(input$dates3061_1)) && input$choices3061_1 == "Выбор по дате") {
     	from=as.Date(input$dates3061_1[1L])
      	to=as.Date(input$dates3061_1[2L])
      	if (from>to) to = from
      	selectdates3061_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3061.1_2 <- data$df3061.1[as.Date(data$df3061.1$"Дата операции") %in% selectdates3061_1_1, ]
    } else if (!is.null(input$text) && input$choices3061_1 == "Выбор по учетному номеру") {
      	data$df3061.1_2 <- data$df3061.1[data$df3061.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices3061_1 == "Выбор вида ценной бумаги") {
      	data$df3061.1_2 <- data$df3061.1[data$df3061.1$"Вид ценной бумаги" == input$text, ]
    } else if (!is.null(input$dates3061_1) && !any(is.na(input$dates3061_1)) && !is.null(input$text) && input$choices3061_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates3061_1[1L])
      	to=as.Date(input$dates3061_1[2L])
      	if (from>to) to = from
      	selectdates3061_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3061.1_2 <- data$df3061.1[as.Date(data$df3061.1$"Дата операции") %in% selectdates3061_1_2 & data$df3061.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3061_1) && !any(is.na(input$dates3061_1)) && !is.null(input$text) && input$choices3061_1 == "Выбор по дате и виду ценной бумаги") {
     	from=as.Date(input$dates3061_1[1L])
      	to=as.Date(input$dates3061_1[2L])
      	if (from>to) to = from
      	selectdates3061_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df3061.1_2 <- data$df3061.1[as.Date(data$df3061.1$"Дата операции") %in% selectdates3061_1_3 & data$df3061.1$"Вид ценной бумаги" == input$text, ]
    } else {
        selectdates3061_1_4 <- unique(data$df3061.1$"Дата операции")
        data$df3061.1_2 <- data$df3061.1[data$df3061.1$"Дата операции" %in% selectdates3061_1_4, ]
    }
}
})  

