observeEvent(input$dates3062_1, {
    start <- ymd(input$dates3062_1[[1]])
    end <- ymd(input$dates3062_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates3062_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates3062_1[[1]]
      r$end <- input$dates3062_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates3062_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table3062_1Item1)) {
    data$df3062.1 <- hot_to_r(input$table3062_1Item1) 

    if (!any(is.na(input$dates3062_1)) && input$choices3062_1 == "Выбор по дате") {
     	from=as.Date(input$dates3062_1[1L])
      	to=as.Date(input$dates3062_1[2L])
      	if (from>to) to = from
      	selectdates3062_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3062.1_2 <- data$df3062.1[as.Date(data$df3062.1$"Дата операции") %in% selectdates3062_1_1, ]
    } else if (!is.null(input$text) && input$choices3062_1 == "Выбор по учетному номеру") {
      	data$df3062.1_2 <- data$df3062.1[data$df3062.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3062_1) && !any(is.na(input$dates3062_1)) && !is.null(input$text) && input$choices3062_1 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates3062_1[1L])
      	to=as.Date(input$dates3062_1[2L])
      	if (from>to) to = from
      	selectdates3062_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3062.1_2 <- data$df3062.1[as.Date(data$df3062.1$"Дата операции") %in% selectdates3062_1_2 & data$df3062.1$"Учетный номер" == input$text, ]
    } else {
        selectdates3062_1_3 <- unique(data$df3062.1$"Дата операции")
        data$df3062.1_2 <- data$df3062.1[data$df3062.1$"Дата операции" %in% selectdates3062_1_3, ]
    }
}
})  

