     	from=as.Date(input$dates3062_5[1L])
      	to=as.Date(input$dates3062_5[2L])
      	if (from>to) to = from
      	selectdates3062_5_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3062.5_2 <- data$df3062.5[as.Date(data$df3062.5$"Дата операции") %in% selectdates3062_5_1, ]
    } else if (!is.null(input$text) && input$choices3062_5 == "Выбор по учетному номеру") {
      	data$df3062.5_2 <- data$df3062.5[data$df3062.5$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3062_5) && !any(is.na(input$dates3062_5)) && !is.null(input$text) && input$choices3062_5 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates3062_5[1L])
      	to=as.Date(input$dates3062_5[2L])
      	if (from>to) to = from
      	selectdates3062_5_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3062.5_2 <- data$df3062.5[as.Date(data$df3062.5$"Дата операции") %in% selectdates3062_5_2 & data$df3062.5$"Учетный номер" == input$text, ]
    } else {
        selectdates3062_5_3 <- unique(data$df3062.5$"Дата операции")
        data$df3062.5_2 <- data$df3062.5[data$df3062.5$"Дата операции" %in% selectdates3062_5_3, ]
