observeEvent(input$dates3110.0, {
    start <- ymd(input$dates3110.0[[1]])
    end <- ymd(input$dates3110.0[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates3110.0", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates3110.0[[1]]
      r$end <- input$dates3110.0[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates3110.0",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table3110.0Item1) && !any(is.na(input$dates3110.0))) {
    data$df3110.0_1 <- hot_to_r(input$table3110.0Item1) 

    if (!any(is.na(input$dates3110.0)) && input$choices3110.0 == "Выбор по дате операции") {
     	from=as.Date(input$dates3110.0[1L])
      	to=as.Date(input$dates3110.0[2L])
      	if (from>to) to = from
      	selectdates3110.0_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3110.0_2 <- data$df3110.0_1[as.Date(data$df3110.0_1$"Дата операции") %in% selectdates3110.0_1, ]
    } else if (!is.null(input$text) && input$choices3110.0 == "Выбор по учетному номеру или названию объекта налогообложения") {
      	data$df3110.0_2 <- data$df3110.0_1[data$df3110.0_1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3110.0) && !any(is.na(input$dates3110.0)) && !is.null(input$text) && input$choices3110.0 == "Выбор по дате операции и учетному номеру или названию объекта налогообложения") {
     	from=as.Date(input$dates3110.0[1L])
      	to=as.Date(input$dates3110.0[2L])
      	if (from>to) to = from
      	selectdates3110.0_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3110.0_2 <- data$df3110.0_1[as.Date(data$df3110.0_1$"Дата операции") %in% selectdates3110.0_2 & data$df3110.0_1$"Учетный номер" == input$text, ]
    } else {
        selectdates3110.0_4 <- unique(data$df3110.0_1$"Дата операции")
        data$df3110.0_2 <- data$df3110.0_1[data$df3110.0_1$"Дата операции" %in% selectdates3110.0_4, ]
