observeEvent(input$dates3310, {
    start <- ymd(input$dates3310[[1]])
    end <- ymd(input$dates3310[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates3310", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates3310[[1]]
      r$end <- input$dates3310[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates3310",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table3310Item1)) {
    data$df3310 <- hot_to_r(input$table3310Item1) 

    if (!any(is.na(input$dates3310)) && input$choices3310 == "Выбор по дате") {
     	from=as.Date(input$dates3310[1L])
      	to=as.Date(input$dates3310[2L])
      	if (from>to) to = from
      	selectdates3310_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3310_2 <- data$df3310[as.Date(data$df3310$"Дата операции") %in% selectdates3310_1, ]
    } else if (!is.null(input$text) && input$choices3310 == "Выбор по учетному номеру") {
      	data$df3310_2 <- data$df3310[data$df3310$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices3310 == "Выбор вида (названия) товаров или услуг по кредиторской задолженности") {
      	data$df3310_2 <- data$df3310[data$df3310$"Вид (название) товаров или услуг по кредиторской задолженности" == input$text, ]
    } else if (!is.null(input$dates3310) && !any(is.na(input$dates3310)) && !is.null(input$text) && input$choices3310 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates3310[1L])
      	to=as.Date(input$dates3310[2L])
      	if (from>to) to = from
      	selectdates3310_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df3310_2 <- data$df3310[as.Date(data$df3310$"Дата операции") %in% selectdates3310_2 & data$df3310$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates3310) && !any(is.na(input$dates3310)) && !is.null(input$text) && input$choices3310 == "Выбор по дате и виду (названию) товаров или услуг по кредиторской задолженности") {
     	from=as.Date(input$dates3310[1L])
      	to=as.Date(input$dates3310[2L])
      	if (from>to) to = from
      	selectdates3310_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df3310_2 <- data$df3310[as.Date(data$df3310$"Дата операции") %in% selectdates3310_3 & data$df3310$"Вид (название) товаров или услуг по кредиторской задолженности" == input$text, ]
    } else {
        selectdates3310_4 <- unique(data$df3310$"Дата операции")
        data$df3310_2 <- data$df3310[data$df3310$"Дата операции" %in% selectdates3310_4, ]
    }
}
})  

  output$table3310Item1 <- renderRHandsontable({
    
   data$df3310[, `Сальдо конечное` := ifelse(!is.na(data$df3310[[10]]) & data$df3310[[10]] != 0,
						data$df3310[[10]], data$df3310[[7]] + data$df3310[[12]] - data$df3310[[14]])]

