      	selectdates3513_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df3513_2 <- data$df3513[as.Date(data$df3513$"Дата операции") %in% selectdates3513_1, ]
    } else if (!is.null(input$text) && input$choices3513 == "Выбор по учетному номеру или ИНН контрагента") {
