    end <- ymd(input$dates4051[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates4051", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates4051[[1]]
      r$end <- input$dates4051[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates4051",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table4051Item1)) {
    data$df4051 <- hot_to_r(input$table4051Item1) 

    if (!any(is.na(input$dates4051)) && input$choices4051 == "Выбор по дате") {
     	from=as.Date(input$dates4051[1L])
      	to=as.Date(input$dates4051[2L])
      	if (from>to) to = from
      	selectdates4051_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df4051_2 <- data$df4051[as.Date(data$df4051$"Дата операции") %in% selectdates4051_1, ]
    } else if (!is.null(input$text) && input$choices4051 == "Выбор по учетному номеру") {
      	data$df4051_2 <- data$df4051[data$df4051$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates4051) && !any(is.na(input$dates4051)) && !is.null(input$text) && input$choices4051 == "Выбор по дате и учетному номеру") {
     	from=as.Date(input$dates4051[1L])
      	to=as.Date(input$dates4051[2L])
      	if (from>to) to = from
      	selectdates4051_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df4051_2 <- data$df4051[as.Date(data$df4051$"Дата операции") %in% selectdates4051_2 & data$df4051$"Учетный номер" == input$text, ]
    } else {
        selectdates4051_4 <- unique(data$df4051$"Дата операции")
        data$df4051_2 <- data$df4051[data$df4051$"Дата операции" %in% selectdates4051_4, ]
    }
}
})  

