 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates4110", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates4110[[1]]
      r$end <- input$dates4110[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates4110",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table4110Item1)) {
    data$df4110 <- hot_to_r(input$table4110Item1) 

    if (!any(is.na(input$dates4110)) && input$choices4110 == "Выбор по дате операции") {
     	from=as.Date(input$dates4110[1L])
      	to=as.Date(input$dates4110[2L])
      	if (from>to) to = from
      	selectdates4110_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df4110_2 <- data$df4110[as.Date(data$df4110$"Дата операции") %in% selectdates4110_1, ]
    } else if (!is.null(input$text) && input$choices4110 == "Выбор по учетному номеру") {
      	data$df4110_2 <- data$df4110[data$df4110$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices4110 == "Выбор вида (названия) товаров или услуг по кредиторской задолженности") {
      	data$df4110_2 <- data$df4110[data$df4110$"Вид (название) товаров или услуг по кредиторской задолженности" == input$text, ]
    } else if (!is.null(input$dates4110) && !any(is.na(input$dates4110)) && !is.null(input$text) && input$choices4110 == "Выбор по дате  операции и учетному номеру") {
     	from=as.Date(input$dates4110[1L])
      	to=as.Date(input$dates4110[2L])
      	if (from>to) to = from
      	selectdates4110_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df4110_2 <- data$df4110[as.Date(data$df4110$"Дата операции") %in% selectdates4110_2 & data$df4110$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates4110) && !any(is.na(input$dates4110)) && !is.null(input$text) && input$choices4110 == "Выбор по дате  операции и виду (названию) товаров или услуг по кредиторской задолженности") {
     	from=as.Date(input$dates4110[1L])
      	to=as.Date(input$dates4110[2L])
      	if (from>to) to = from
      	selectdates4110_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df4110_2 <- data$df4110[as.Date(data$df4110$"Дата операции") %in% selectdates4110_3 & data$df4110$"Вид (название) товаров или услуг по кредиторской задолженности" == input$text, ]
    } else {
        selectdates4110_4 <- unique(data$df4110$"Дата операции")
        data$df4110_2 <- data$df4110[data$df4110$"Дата операции" %in% selectdates4110_4, ]
    }
}
})  

