observeEvent(input$dates4210, {
    start <- ymd(input$dates4210[[1]])
    end <- ymd(input$dates4210[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates4210", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates4210[[1]]
      r$end <- input$dates4210[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates4210",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table4210Item1)) {
    data$df4210 <- hot_to_r(input$table4210Item1) 

    if (!any(is.na(input$dates4210)) && input$choices4210 == "Выбор по дате операции") {
     	from=as.Date(input$dates4210[1L])
      	to=as.Date(input$dates4210[2L])
      	if (from>to) to = from
      	selectdates4210_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df4210_2 <- data$df4210[as.Date(data$df4210$"Дата операции") %in% selectdates4210_1, ]
    } else if (!is.null(input$text) && input$choices4210 == "Выбор по учетному номеру") {
      	data$df4210_2 <- data$df4210[data$df4210$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates4210) && !any(is.na(input$dates4210)) && !is.null(input$text) && input$choices4210 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates4210[1L])
      	to=as.Date(input$dates4210[2L])
      	if (from>to) to = from
      	selectdates4210_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df4210_2 <- data$df4210[as.Date(data$df4210$"Дата операции") %in% selectdates4210_2 & data$df4210$"Учетный номер" == input$text, ]
    } else {
        selectdates4210_4 <- unique(data$df4210$"Дата операции")
        data$df4210_2 <- data$df4210[data$df4210$"Дата операции" %in% selectdates4210_4, ]
    }
}
})  

  output$table4210Item1 <- renderRHandsontable({
    
   data$df4210[, `Сальдо конечное` := ifelse(!is.na(data$df4210[[7]]) & data$df4210[[7]] != 0,
						data$df4210[[7]], data$df4210[[5]] + data$df4210[[8]] - data$df4210[[9]])]

    rhandsontable(data$df4210, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
