     	from=as.Date(input$dates4411[1L])
      	to=as.Date(input$dates4411[2L])
      	if (from>to) to = from
      	selectdates4411_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df4411_2 <- data$df4411[as.Date(data$df4411$"Дата операции") %in% selectdates4411_1, ]
    } else if (!is.null(input$text) && input$choices4411 == "Выбор по учетному номеру или ИНН контрагента") {
      	data$df4411_2 <- data$df4411[data$df4411$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates4411) && !any(is.na(input$dates4411)) && !is.null(input$text) && input$choices4411 == "Выбор по дате операции и учетному номеру или ИНН контрагента") {
     	from=as.Date(input$dates4411[1L])
      	to=as.Date(input$dates4411[2L])
      	if (from>to) to = from
      	selectdates4411_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df4411_2 <- data$df4411[as.Date(data$df4411$"Дата операции") %in% selectdates4411_2 & data$df4411$"Учетный номер" == input$text, ]
    } else {
        selectdates4411_4 <- unique(data$df4411$"Дата операции")
        data$df4411_2 <- data$df4411[data$df4411$"Дата операции" %in% selectdates4411_4, ]
    }
}
})  

