    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates5522", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates5522[[1]]
      r$end <- input$dates5522[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates5522",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table5522Item1)) {
    data$df5522 <- hot_to_r(input$table5522Item1) 

    if (!any(is.na(input$dates5522)) && input$choices5522 == "Выбор по дате операции") {
     	from=as.Date(input$dates5522[1L])
      	to=as.Date(input$dates5522[2L])
      	if (from>to) to = from
      	selectdates5522_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df5522_2 <- data$df5522[as.Date(data$df5522$"Дата операции") %in% selectdates5522_1, ]
    } else if (!is.null(input$text) && input$choices5522 == "Выбор по номеру счета, по которому составлен резерв") {
      	data$df5522_2 <- data$df5522[data$df5522$`Номер счета, по которому составлен резерв` == input$text, ]
    } else if (!is.null(input$dates5522) && !any(is.na(input$dates5522)) && !is.null(input$text) && input$choices5522 == "Выбор по дате операции и номеру счета, по которому составлен резерв") {
     	from=as.Date(input$dates5522[1L])
      	to=as.Date(input$dates5522[2L])
      	if (from>to) to = from
      	selectdates5522_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df5522_2 <- data$df5522[as.Date(data$df5522$"Дата операции") %in% selectdates5522_2 & data$df5522$`Номер счета, по которому составлен резерв` == input$text, ]
    } else {
        selectdates5522_4 <- unique(data$df5522$"Дата операции")
        data$df5522_2 <- data$df5522[data$df5522$"Дата операции" %in% selectdates5522_4, ]
    }
}
})  

  output$table5522Item1 <- renderRHandsontable({
    
   data$df5522[, `Сальдо конечное` := data$df5522[[6]] + data$df5522[[7]] - data$df5522[[8]]]

    rhandsontable(data$df5522, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui5522 <- renderUI({
