observeEvent(input$dates5600, {
    start <- ymd(input$dates5600[[1]])
    end <- ymd(input$dates5600[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates5600", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates5600[[1]]
      r$end <- input$dates5600[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates5600",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

observe({
    if (!any(is.na(input$dates5600))) {
      from=as.Date(input$dates5600[1L])
      to=as.Date(input$dates5600[2L])
      if (from>to) to = from
      selectdates5610_1 <- seq.Date(from=from,
                               to=to, by = "day")
     data$df5610_1 <- data$df5610[as.Date(data$df5610$`Дата операции`) %in% selectdates5610_1, ]
    } else {
      selectdates5610_2 <- unique(as.Date(data$df5610$`Дата операции`))
      data$df5610_1 <- data$df5610[data$df5610$`Дата операции` %in% selectdates5610_2, ]
    }
  })

  observe({
    if(!is.null(input$table5610Item1) && !any(is.na(input$table5610Item1)))
      data$df5610_1<- hot_to_r(input$table5610Item1)
  })

observe({
    if (!any(is.na(input$dates5600))) {
      from=as.Date(input$dates5600[1L])
      to=as.Date(input$dates5600[2L])
      if (from>to) to = from
      selectdates5620_1 <- seq.Date(from=from,
                               to=to, by = "day")
     data$df5620_1 <- data$df5620[as.Date(data$df5620$`Дата операции`) %in% selectdates5620_1, ]
    } else {
      selectdates5620_2 <- unique(as.Date(data$df5620$`Дата операции`))
      data$df5620_1 <- data$df5620[data$df5620$`Дата операции` %in% selectdates5620_2, ]
    }
  })

  observe({
    if(!is.null(input$table5620Item1) && !any(is.na(input$table5620Item1)))
      data$df5620_1<- hot_to_r(input$table5620Item1)
  })

observe({
  data$df5600[1, 2:5] <- data$df5610_1[, list(
    `Сальдо начальное` = sum(`Сальдо начальное`[1L], na.rm = TRUE),
    Кредит = sum(`Кредит`, na.rm = TRUE),
    Дебет = sum(`Дебет`, na.rm = TRUE),
    `Сальдо конечное` = sum(`Сальдо конечное`[.N], na.rm = TRUE)
  ), by=`Ф.И.О. (или юридическое наименование) выгодополучателя`][, .(
    `Сальдо начальное` = sum(`Сальдо начальное`),
    Дебет = sum(Дебет),
    Кредит = sum(Кредит),
    `Сальдо конечное` = sum(`Сальдо конечное`)
  )]
})

observe({
  data$df5600[2, 2:5] <- data$df5620_1[, list(
    `Сальдо начальное` = sum(`Сальдо начальное`[1L], na.rm = TRUE),
    Кредит = sum(`Кредит`, na.rm = TRUE),
    Дебет = sum(`Дебет`, na.rm = TRUE),
    `Сальдо конечное` = sum(`Сальдо конечное`[.N], na.rm = TRUE)
  ), by=`Ф.И.О. (или юридическое наименование) выгодополучателя`][, .(
    `Сальдо начальное` = sum(`Сальдо начальное`),
    Дебет = sum(Дебет),
    Кредит = sum(Кредит),
    `Сальдо конечное` = sum(`Сальдо конечное`)
  )]
})

observe({ data$df5600[3, 2:5] <- data$df5600[, .SD[1:2, lapply(.SD, sum)], .SDcols = 2:5] })

