#5610

observeEvent(input$dates5610, {
    start <- ymd(input$dates5610[[1]])
    end <- ymd(input$dates5610[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates5610", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates5610[[1]]
      r$end <- input$dates5610[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates5610",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

observe({ if (!is.null(input$table5610Item1)) {
    data$df5610 <- hot_to_r(input$table5610Item1) 

    if (!any(is.na(input$dates5610)) && input$choices5610 == "Выбор по дате операции") {
     	from=as.Date(input$dates5610[1L])
      	to=as.Date(input$dates5610[2L])
      	if (from>to) to = from
      	selectdates5610_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df5610_2 <- data$df5610[as.Date(data$df5610$"Дата операции") %in% selectdates5610_1, ]
    } else if (!is.null(input$text) && input$choices5610 == "Выбор по Ф.И.О. (или юридическому наименованию) выгодополучателя") {
      	data$df5610_2 <- data$df5610[data$df5610$"Ф.И.О. (или юридическое наименование) выгодополучателя" == input$text, ]
    } else if (!is.null(input$dates5610) && !any(is.na(input$dates5610)) && !is.null(input$text) && input$choices5610 == "Выбор по дате операции и Ф.И.О. (или юридическому наименованию) выгодополучателя") {
     	from=as.Date(input$dates5610[1L])
      	to=as.Date(input$dates5610[2L])
      	if (from>to) to = from
      	selectdates5610_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df5610_2 <- data$df5610[as.Date(data$df5610$"Дата операции") %in% selectdates5610_2 & data$df5610$"Ф.И.О. (или юридическое наименование) выгодополучателя" == input$text, ]
    } else {
        selectdates5610_4 <- unique(data$df5610$"Дата операции")
        data$df5610_2 <- data$df5610[data$df5610$"Дата операции" %in% selectdates5610_4, ]
    }
}
})  

  output$table5610Item1 <- renderRHandsontable({
    
   data$df5610[, `Сальдо конечное` := data$df5610[[6]] + data$df5610[[7]] - data$df5610[[8]]]

    rhandsontable(data$df5610, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui5610 <- renderUI({
    if (input$choices5610 == "Выбор по дате операции") {
      	dateRangeInput("dates5610", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices5610 == "Выбор по Ф.И.О. (или юридическому наименованию) выгодополучателя") {
        textInput("text", "Укажите Ф.И.О. (или юридическое наименование) выгодополучателя:")
    } else if (input$choices5610 == "Выбор по дате операции и Ф.И.О. (или юридическому наименованию) выгодополучателя") {
      fluidRow(
       	dateRangeInput("dates5610", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите Ф.И.О. (или юридическое наименование) выгодополучателя:")
      )
    }
  })

  output$table5610Item2 <- renderRHandsontable({
    rhandsontable(data$df5610_2, colWidths = 150, height = 600, readOnly=TRUE, contextMenu = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })

  output$download_df5610 <- downloadHandler(
    filename = function() { "df5610.xlsx" },
    content = function(file) {
      write.xlsx(data$df5610, file)
  })

  output$download_df5610_2 <- downloadHandler(
    filename = function() { "df5610_2.xlsx" },
    content = function(file) {
      write.xlsx(data$df5610_2, file)
  })

