observeEvent(input$dates6210, {
    start <- ymd(input$dates6210[[1]])
    end <- ymd(input$dates6210[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates6210", 
        start = r$start,
        end = r$end
