      	selectdates6261.1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df6261.1_2 <- data$df6261.1[as.Date(data$df6261.1$"Дата операции") %in% selectdates6261.1_3 & data$df6261.1$"Счет № статьи дохода" == input$text, ]
