observe({ if (!is.null(input$table7461_1Item1)) {
    data$df7461.1 <- hot_to_r(input$table7461_1Item1) 

    if (!any(is.na(input$dates7461.1)) && input$choices7461.1 == "Выбор по дате операции") {
     	from=as.Date(input$dates7461.1[1L])
      	to=as.Date(input$dates7461.1[2L])
      	if (from>to) to = from
      	selectdates7461.1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df7461.1_2 <- data$df7461.1[as.Date(data$df7461.1$"Дата операции") %in% selectdates7461.1_1, ]
    } else if (!is.null(input$text) && input$choices7461.1 == "Выбор по номеру первичного документа") {
      	data$df7461.1_2 <- data$df7461.1[data$df7461.1$"Номер первичного документа" == input$text, ]
    } else if (!is.null(input$text) && input$choices7461.1 == "Выбор по статье расхода") {
      	data$df7461.1_2 <- data$df7461.1[data$df7461.1$"Счет № статьи расхода" == input$text, ]
    } else if (!is.null(input$dates7461.1) && !any(is.na(input$dates7461.1)) && !is.null(input$text) && input$choices7461.1 == "Выбор по дате операции и номеру первичного документа") {
     	from=as.Date(input$dates7461.1[1L])
      	to=as.Date(input$dates7461.1[2L])
      	if (from>to) to = from
      	selectdates7461.1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df7461.1_2 <- data$df7461.1[as.Date(data$df7461.1$"Дата операции") %in% selectdates7461.1_2 & data$df7461.1$"Номер первичного документа" == input$text, ]
    } else if (!is.null(input$dates7461.1) && !any(is.na(input$dates7461.1)) && !is.null(input$text) && input$choices7461.1 == "Выбор по дате операции и статье расхода") {
     	from=as.Date(input$dates7461.1[1L])
      	to=as.Date(input$dates7461.1[2L])
      	if (from>to) to = from
      	selectdates7461.1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df7461.1_2 <- data$df7461.1[as.Date(data$df7461.1$"Дата операции") %in% selectdates7461.1_3 & data$df7461.1$"Счет № статьи расхода" == input$text, ]
    } else {
        selectdates7461.1_4 <- unique(data$df7461.1$"Дата операции")
        data$df7461.1_2 <- data$df7461.1[data$df7461.1$"Дата операции" %in% selectdates7461.1_4, ]
    }
}
})

