      	selectdates7483.1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df7483.1_2 <- data$df7483.1[as.Date(data$df7483.1$"Дата операции") %in% selectdates7483.1_1, ]
    } else if (!is.null(input$text) && input$choices7483.1 == "Выбор по номеру первичного документа") {
      	data$df7483.1_2 <- data$df7483.1[data$df7483.1$"Номер первичного документа" == input$text, ]
    } else if (!is.null(input$text) && input$choices7483.1 == "Выбор по статье расхода") {
      	data$df7483.1_2 <- data$df7483.1[data$df7483.1$"Счет № статьи расхода" == input$text, ]
