      	selectdates7483.1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df7483.1_2 <- data$df7483.1[as.Date(data$df7483.1$"Дата операции") %in% selectdates7483.1_2 & data$df7483.1$"Номер первичного документа" == input$text, ]
    } else if (!is.null(input$dates7483.1) && !any(is.na(input$dates7483.1)) && !is.null(input$text) && input$choices7483.1 == "Выбор по дате операции и статье расхода") {
     	from=as.Date(input$dates7483.1[1L])
      	to=as.Date(input$dates7483.1[2L])
      	if (from>to) to = from
      	selectdates7483.1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df7483.1_2 <- data$df7483.1[as.Date(data$df7483.1$"Дата операции") %in% selectdates7483.1_3 & data$df7483.1$"Счет № статьи расхода" == input$text, ]
