}, ignoreInit = TRUE)

observe({ if (!is.null(input$table7510Item1) && !any(is.na(input$dates7510))) {
    data$df7510 <- hot_to_r(input$table7510Item1) 

    if (!any(is.na(input$dates7510)) && input$choices7510 == "Выбор по дате учета") {
     	from=as.Date(input$dates7510[1L])
      	to=as.Date(input$dates7510[2L])
      	if (from>to) to = from
      	selectdates7510_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df7510_2 <- data$df7510[as.Date(data$df7510$"Дата учета") %in% selectdates7510_1, ]
    } else if (!is.null(input$text) && input$choices7510 == "Выбор по номеру учета объекта инвестиции") {
      	data$df7510_2 <- data$df7510[data$df7510$"Номер учета (реквизиты) объекта инвестиции" == input$text, ]
    } else if (!is.null(input$dates7510) && !any(is.na(input$dates7510)) && !is.null(input$text) && input$choices7510 == "Выбор по дате и номеру учета объекта инвестиции") {
     	from=as.Date(input$dates7510[1L])
      	to=as.Date(input$dates7510[2L])
      	if (from>to) to = from
      	selectdates7510_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df7510_2 <- data$df7510[as.Date(data$df7510$"Дата учета") %in% selectdates7510_2 & data$df7510$"Номер учета (реквизиты) объекта инвестиции" == input$text, ]
    } else {
        selectdates7510_4 <- unique(data$df7510$"Дата учета")
        data$df7510_2 <- data$df7510[data$df7510$"Дата учета" %in% selectdates7510_4, ]
    }
}
})  

  output$table7510Item1 <- renderRHandsontable({

    rhandsontable(data$df7510, colWidths = 150, height = 600, allowInvalid=FALSE, fixedColumnsLeft = 2) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")|>
      hot_cols(manualColumnResize = TRUE)
  })
  
  output$nested_ui7510 <- renderUI({
    if (input$choices7510 == "Выбор по дате учета") {
      	dateRangeInput("dates7510", "Выберите период времени:",
