    } else if (input$choices7510 == "Выбор по дате и номеру учета объекта инвестиции") {
      fluidRow(
       	dateRangeInput("dates7510", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите номер учета (реквизиты) объекта инвестиции:")
      )
    } 
  })

