#Отчет о финансовых результатах

#calculation of DFRevenue

observe({
  req(data$df6010, data$df6020, data$df6030, input$year_range, input$period)
  
  current_yr <- year(Sys.Date())
  
  selected_years <- switch(input$year_range,
    "Текущий год" = current_yr,
    "Предыдущий год" = current_yr - 1,
    "Позапрошлый год" = current_yr - 2,
    "Текущий и предыдущий годы" = c(current_yr, current_yr - 1),
    "Текущий, предыдущий и позапрошлый годы" = c(current_yr, current_yr - 1, current_yr - 2),
    "Предыдущий и позапрошлый годы" = c(current_yr - 1, current_yr - 2)
  )
  
  russian_months <- c("Январь", "Февраль", "Март", "Апрель", "Май", "Июнь",
                     "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь")
  
  period_info <- switch(input$period,
    "по месяцам" = list(labels = russian_months, count = 12, extract = function(d) month(d)),
    "по кварталам" = list(labels = paste0("Квартал ",1:4), count = 4, extract = function(d) quarter(d)),
    "полугодовой" = list(labels = c("Первое полугодие","Второе полугодие"), count = 2, 
                        extract = function(d) ifelse(month(d) <= 6, 1, 2)),
    "годовой" = list(labels = "Годовой", count = 1, extract = function(d) 1)
  )
  
  all_cols <- unlist(lapply(selected_years, function(yr) 
  paste(period_info$labels[1:period_info$count], yr)))
  
  aggregate_table <- function(dt) {
    res <- setNames(rep(0, length(all_cols)), all_cols)
    if (nrow(dt) == 0) return(res)
    
    dates <- as.Date(dt$`Дата операции`, format="%Y-%m-%d")
    valid <- !is.na(dates) & year(dates) %in% selected_years
    if (!any(valid)) return(res)
    
    df <- data.table(
      y = year(dates[valid]),
      p = period_info$extract(dates[valid]),
      k = dt$Кредит[valid]
    )[y %in% selected_years, .(s = sum(k, na.rm=TRUE)), by=.(y,p)]
    
    for(i in 1:nrow(df)) {
      col <- paste(period_info$labels[df$p[i]], df$y[i])
      if (col %in% all_cols) res[col] <- df$s[i]
    }
    res
  }
  
  sum6010 <- aggregate_table(data$df6010)
  sum6020 <- aggregate_table(data$df6020)
  sum6030 <- aggregate_table(data$df6030)
  
  df <- data.table(
    Наименование = c(
      "Доход от реализации продукции, товаров и услуг",
      "Возврат проданной продукции", 
      "Скидки с цены и продаж",
      "ВЫРУЧКА")
  )
  
  for(col in all_cols) df[, (col) := 0]
  
  df[1, (all_cols) := as.list(sum6010)]
  df[2, (all_cols) := as.list(sum6020)]
  df[3, (all_cols) := as.list(sum6030)]
  
  # Corrected lines using .SD and .SDcols
  df[4, (all_cols) := lapply(all_cols, function(col) {
						df[[col]][1] -
						df[[col]][2] -
						df[[col]][3]
   })]
  
  data$dfRevenue <- df
  })

  output$tableRevenueItem1 <- renderRHandsontable({
    rhandsontable(data$dfRevenue, colWidths = 150, height = 200, readOnly = TRUE, 
		fixedColumnsLeft = 1, manualColumnResize = TRUE, contextMenu = FALSE) |>
	hot_col(1, width = 300)})

  output$download_dfRevenue <- downloadHandler(
    filename = function() { "dfRevenue.xlsx" },
    content = function(file) {
      write.xlsx(data$dfRevenue, file)})

#******************************************

#calculation of DFGrossProfit 

observe({
  req(data$dfRevenue, input$year_range, input$period)

  # Ensure DFGrossProfit has the same structure as DFRevenue
  revenue_cols <- names(data$dfRevenue)
  gross_profit_cols <- names(data$dfGrossProfit)
  
  # Add missing columns to DFGrossProfit
  missing_cols <- setdiff(revenue_cols, gross_profit_cols)
  if(length(missing_cols) > 0) {
    data$dfGrossProfit[, (missing_cols) := 0]
  }
  
  # Remove extra columns (if any)
  extra_cols <- setdiff(gross_profit_cols, revenue_cols)
  if(length(extra_cols) > 0) {
    data$dfGrossProfit[, (extra_cols) := NULL]
  }
  
  # Update Выручка row (1st row of DFGrossProfit) from ВЫРУЧКА (4th row of DFRevenue)
  if(nrow(data$dfRevenue) >= 4) {
    numeric_cols <- names(data$dfRevenue)[sapply(data$dfRevenue, is.numeric)]
    data$dfGrossProfit[1, (numeric_cols) := data$dfRevenue[4, .SD, .SDcols = numeric_cols]]
  }
})

# Replicating the 4th row of DFRevenue as the 1st row of DFGrossProfit

observe({
  req(data$dfRevenue, input$year_range, input$period)
  if(nrow(data$dfRevenue) >= 4) {
    # Get the last column that has numeric data (excluding the first name column)
    last_col <- ncol(data$dfRevenue)
    while(is.character(data$dfRevenue[[last_col]]) && last_col > 1) {
      last_col <- last_col - 1
    }
    
    # Update GrossProfit table
    if(last_col > 1) {
      # Set first row (Выручка) to be equal to fourth row of Revenue (ВЫРУЧКА)
      data$dfGrossProfit[1, 2:last_col] <- data$dfRevenue[4, 2:last_col]
    }
  }
})

# Correct synchronization and calculation for DFGrossProfit

observe({
  req(data$dfRevenue, data$df7010_1, input$year_range, input$period)
  
  # Unified period calculation logic
  current_yr <- year(Sys.Date())
  selected_years <- switch(input$year_range,
    "Текущий год" = current_yr,
    "Предыдущий год" = current_yr - 1,
    "Позапрошлый год" = current_yr - 2,
    "Текущий и предыдущий годы" = c(current_yr, current_yr - 1),
    "Текущий, предыдущий и позапрошлый годы" = c(current_yr, current_yr - 1, current_yr - 2),
    "Предыдущий и позапрошлый годы" = c(current_yr - 1, current_yr - 2)
  )
  
  russian_months <- c("Январь", "Февраль", "Март", "Апрель", "Май", "Июнь",
                     "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь")
  
  period_info <- switch(input$period,
    "по месяцам" = list(labels = russian_months, count = 12, extract = month),
    "по кварталам" = list(labels = paste0("Квартал ",1:4), count = 4, extract = quarter),
    "полугодовой" = list(labels = c("Первое полугодие","Второе полугодие"), count = 2, 
                        extract = function(d) ifelse(month(d) <= 6, 1, 2)),
    "годовой" = list(labels = "Годовой", count = 1, extract = function(d) 1)
  )
  
  # Generate column names safely
  all_cols <- unlist(lapply(selected_years, function(yr) {
    if(period_info$count > length(period_info$labels)) return(character(0))
    paste(period_info$labels[1:period_info$count], yr)
  }))
  
  # Exit if no columns generated
  if(length(all_cols) == 0) {
    data$dfGrossProfit <- DFGrossProfit
    return()
  }
  
  # 1. Sync structure from dfRevenue
  data$dfGrossProfit <- data.table(
    Наименование = DFGrossProfit$Наименование
  )
  data$dfGrossProfit[, (all_cols) := 0]
  
  # 2. Update Выручка from dfRevenue
  if(nrow(data$dfRevenue) >= 4) {
    revenue_values <- data$dfRevenue[4, .SD, .SDcols = all_cols]
    data$dfGrossProfit[1, (all_cols) := as.list(revenue_values)]
  }
  
  # 3. Aggregate Debit sums from DF7010_1
  aggregate_debits <- function(dt) {
    res <- setNames(rep(0, length(all_cols)), all_cols)
    if(nrow(dt) == 0) return(res)
    
    dates <- as.Date(dt$`Дата операции`, "%Y-%m-%d")
    valid_dates <- which(!is.na(dates) & year(dates) %in% selected_years)
    
    if(length(valid_dates) == 0) return(res)
    
    dt_valid <- dt[valid_dates]
    dt_valid[, `:=`(
      year = year(dates[valid_dates]),
      period = period_info$extract(dates[valid_dates])
    )]
    
    agg <- dt_valid[, .(sum = sum(`Дебет`, na.rm = TRUE)), 
                   by = .(year, period)]
    
    for(i in seq_len(nrow(agg))) {
      col_name <- paste(period_info$labels[agg$period[i]], agg$year[i])
      if(col_name %in% all_cols) res[[col_name]] <- agg$sum[i]
    }
    res
  }
  
  # 4. Update Себестоимость
  sum_debit <- aggregate_debits(data$df7010_1)
  data$dfGrossProfit[2, (all_cols) := as.list(sum_debit)]
  
  # 5. Calculate Валовый доход
  data$dfGrossProfit[3, (all_cols) := data$dfGrossProfit[1, .SD, .SDcols = all_cols] - 
                       data$dfGrossProfit[2, .SD, .SDcols = all_cols]]
})

output$tableGrossProfitItem1 <- renderRHandsontable({
  rhandsontable(data$dfGrossProfit, colWidths = 150, height = 200, readOnly = TRUE, 
		fixedColumnsLeft = 1, manualColumnResize = TRUE, contextMenu = FALSE) |>
    hot_col(1, width = 300)})

output$download_dfGrossProfit <- downloadHandler(
  filename = function() { "dfGrossProfit.xlsx" },
  content = function(file) {
    write.xlsx(data$dfGrossProfit, file)})

