# dfSumOtherOperatingExpenses Calculation

observe({
  req(input$period, input$year_range, data$dfOtherOperatingExpenses, data$dfShareInLossInvestObject1)
  
  # Correct reference to reactive data
  common_cols <- intersect(
    names(data$dfOtherOperatingExpenses),
    names(data$dfShareInLossInvestObject1)
  )
  common_cols <- setdiff(common_cols, "Наименование")  # Exclude name column
  
  if (length(common_cols) == 0) return()  # Check for valid columns
  
  sum_operating <- data$dfOtherOperatingExpenses[, lapply(.SD, sum), .SDcols = common_cols]
  sum_share <- data$dfShareInLossInvestObject1[, lapply(.SD, sum), .SDcols = common_cols]
  
  total_sum <- sum_operating + sum_share
  data$dfSumOtherOperatingExpenses <- data.table(
    Наименование = "Прочие операционные расходы",
    total_sum
  )
}) %>% bindEvent(data$dfOtherOperatingExpenses, data$DFShareInLossInvestObject1)

  output$tableSumOtherOperatingExpensesItem1 <- renderRHandsontable({
    rhandsontable(data$dfSumOtherOperatingExpenses, colWidths = 150, height = 250,
		readOnly = TRUE, fixedColumnsLeft = 1, 
		manualColumnResize = TRUE, contextMenu = FALSE) |>
      hot_col(1, width = 300)
  })
  
  output$download_dfSumOtherOperatingExpenses <- downloadHandler(
    filename = function() { "dfSumOtherOperatingExpenses.xlsx" },
    content = function(file) { write.xlsx(data$dfSumOtherOperatingExpenses, file) })

