    "полугодовой" = list(labels = c("Первое полугодие","Второе полугодие"), count = 2, 
                        extract = function(d) ifelse(month(d) <= 6, 1, 2)),
    "годовой" = list(labels = "Годовой", count = 1, extract = function(d) 1)
  )
  
  all_cols <- unlist(lapply(selected_years, function(yr) 
    paste(period_info$labels[1:period_info$count], yr)))
  
  aggregate_credits <- function(dt) {
    res <- setNames(rep(0, length(all_cols)), all_cols)
    if (nrow(dt) == 0) return(res)
    
    dates <- as.Date(dt$`Дата учета`, format = "%Y-%m-%d")
    valid <- !is.na(dates) & year(dates) %in% selected_years
    if (!any(valid)) return(res)
    
    df <- data.table(
      y = year(dates[valid]),
      p = period_info$extract(dates[valid]),
      credit = dt$`Сумма доли в прибыли объекта инвестиции за период`[valid]
    )[y %in% selected_years, .(s = sum(credit, na.rm = TRUE)), by = .(y, p)]
    
    for (i in 1:nrow(df)) {
      col <- paste(period_info$labels[df$p[i]], df$y[i])
      if (col %in% all_cols) res[col] <- df$s[i]
    }
    res
  }
  
  dfShareInRevenueInvestObject1 <- data$dfShareInRevenueInvestObject1
  if (nrow(dfShareInRevenueInvestObject1) == 0) return()
  
  df <- data.table(Наименование = as.character(dfShareInRevenueInvestObject1$Наименование))
  for (col in all_cols) df[, (col) := 0]
  
  for (i in 1:nrow(df)) {
    expense <- df$Наименование[i]
    if (is.na(expense)) next
    
    dt <- switch(expense,
		"6310.Доля в прибыли материнской компании и компаний с совместным контролем или значительным влиянием" = data$df6310,
		"6320.Доля в прибыли дочерних компаний и других организации той же группы" = data$df6320,
		"6330.Доля в прибыли ассоциированных организаций и совместных предприятий" = data$df6330,
		NULL)
    
    if (is.null(dt)) next
    
    sum_credit <- aggregate_credits(dt)
    df[i, (all_cols) := as.list(sum_credit)]
  }
  data$dfShareInRevenueInvestObject1 <- df
})

