# dfSumOtherOperatingEarnings calculation

observe({
  req(input$period, input$year_range, data$dfOtherOperatingEarnings, data$dfShareInRevenueInvestObject1)
  
  # Correct reference to reactive data
  common_cols <- intersect(
    names(data$dfOtherOperatingEarnings),
    names(data$dfShareInRevenueInvestObject1)
  )
  common_cols <- setdiff(common_cols, "Наименование")  # Exclude name column
  
  if (length(common_cols) == 0) return()  # Check for valid columns
  
  sum_operating <- data$dfOtherOperatingEarnings[, lapply(.SD, sum), .SDcols = common_cols]
  sum_share <- data$dfShareInRevenueInvestObject1[, lapply(.SD, sum), .SDcols = common_cols]
  
  total_sum <- sum_operating + sum_share
  data$dfSumOtherOperatingEarnings <- data.table(
    Наименование = "Прочие операционные доходы",
    total_sum
  )
}) %>% bindEvent(data$dfOtherOperatingEarnings, data$DFShareInRevenueInvestObject1)

  output$tableSumOtherOperatingEarningsItem1 <- renderRHandsontable({
    rhandsontable(data$dfSumOtherOperatingEarnings, colWidths = 150, height = 250,
