# Operating Income Calculation

observe({
  req(data$dfGrossProfit, data$dfAdminSale, data$dfSumOtherOperatingExpenses,
	data$dfSumOtherOperatingEarnings, input$year_range, input$period)
  
  period_cols <- names(data$dfGrossProfit)[-1]
  
  # Initialize Operating Income with correct structure
  data$dfOperatingIncome <- data.table(
    Наименование = "ОПЕРАЦИОННАЯ ПРИБЫЛЬ (УБЫТОК)"
  )
  data$dfOperatingIncome[, (period_cols) := 0]
  
  # Calculate each period column
  for (col in period_cols) {
    gross_profit <- data$dfGrossProfit[Наименование == "ВАЛОВЫЙ ДОХОД", ..col][[1]]
    admin_sale_total <- sum(data$dfAdminSale[[col]], na.rm = TRUE)
    other_expenses_total <- sum(data$dfSumOtherOperatingExpenses[[col]], na.rm = TRUE)
    other_earnings_total <- sum(data$dfSumOtherOperatingEarnings[[col]], na.rm = TRUE)
    
    # Calculate Operating Income for the column
    data$dfOperatingIncome[, (col) := gross_profit - admin_sale_total - other_expenses_total + other_earnings_total]
  }
})
    
 output$tableOperatingIncomeItem1 <- renderRHandsontable({
