#dynamic calculation of dfEBITDA

#define the custom-operator "%||%"
`%||%` <- function(a, b) if (!is.null(a) && length(a) > 0) a else b

#EBITDA calculation

observe({
  req(data$dfEBIT, data$dfSumDandA, input$year_range, input$period)
  
  # Get period columns from existing structure
  period_cols <- names(data$dfEBIT)[-1]
  if(length(period_cols) == 0) return()
  
  # Initialize EBITDA with proper structure
  data$dfEBITDA <- data.table(
    Наименование = "ПРИБЫЛЬ ДО ВЫЧЕТА ПРОЦЕНТОВ, НАЛОГОВ, ИЗНОСА И АМОРТИЗАЦИИ (EBITDA)"
  )
  data$dfEBITDA[, (period_cols) := 0]
  
  # Calculate values with null coalescing
  for(col in period_cols) {
    if(col %in% names(data$dfEBIT) && col %in% names(data$dfSumDandA)) {
      ebit_value <- data$dfEBIT[[col]][1] %||% 0
      sumdanda_value <- data$dfSumDandA[[col]][1] %||% 0
      data$dfEBITDA[, (col) := as.numeric(ebit_value) + as.numeric(sumdanda_value)]
    }
  }
})

  output$tableEBITDAItem1 <- renderRHandsontable({
    rhandsontable(data$dfEBITDA, colWidths = 150, height = 200, readOnly = TRUE, fixedColumnsLeft = 1, 
		manualColumnResize = TRUE, contextMenu = FALSE) |>
      hot_col(1, width = 450)
  })
  
  output$download_dfEBITDA <- downloadHandler(
    filename = function() { "dfEBITDA.xlsx" },
    content = function(file) { write.xlsx(data$dfEBITDA, file) })

