# Non-Operating Income Calculation

observe({
  req(
    data$dfGrossProfit, data$dfAdminSale, 
    data$dfSumNonOperatingExpenses, data$dfSumNonOperatingEarnings,
    input$year_range, input$period
  )
  
  period_cols <- names(data$dfGrossProfit)[-1]
  
  # Initialize Operating Income with correct structure
  data$dfNonOperatingIncome <- data.table(
    Наименование = "НЕОПЕРАЦИОННАЯ ПРИБЫЛЬ (УБЫТОК)"
  )
  data$dfNonOperatingIncome[, (period_cols) := 0]
  
  # Calculate each period column
  for (col in period_cols) {
    nonoperating_expenses_total <- sum(data$dfSumNonOperatingExpenses[[col]], na.rm = TRUE)
    nonoperating_earnings_total <- sum(data$dfSumNonOperatingEarnings[[col]], na.rm = TRUE)
    
    # Calculate Operating Income for the column
    data$dfNonOperatingIncome[, (col) :=  nonoperating_earnings_total - nonoperating_expenses_total]
  }
 })
    
 output$tableNonOperatingIncomeItem1 <- renderRHandsontable({
   rhandsontable(data$dfNonOperatingIncome, colWidths = 150, height = 200, readOnly = TRUE,
