#dynamic calculation of dfEBIT

#define the custom-operator "%||%"
`%||%` <- function(a, b) if (!is.null(a) && length(a) > 0) a else b

#EBIT calculation

observe({
  req(data$dfOperatingIncome, data$dfNonOperatingIncome, input$year_range, input$period)
  
  # Get period columns from existing structure
  period_cols <- names(data$dfGrossProfit)[-1]
  if(length(period_cols) == 0) return()
  
  # Initialize EBIT with proper structure
  data$dfEBIT <- data.table(
    Наименование = "ПРИБЫЛЬ ДО ВЫЧЕТА ПРОЦЕНТОВ И НАЛОГОВ (EBIT)"
  )
  data$dfEBIT[, (period_cols) := 0]
  
  # Calculate values with null coalescing

  for(col in period_cols) {
    if(col %in% names(data$dfOperatingIncome) && col %in% names(data$dfNonOperatingIncome)) {
      operating_income <- data$dfOperatingIncome[[col]][1] %||% 0
      nonoperating_income <- data$dfNonOperatingIncome[[col]][1] %||% 0
      data$dfEBIT[, (col) := as.numeric(operating_income) + as.numeric(nonoperating_income)]
    }
  }
})

  output$tableEBITItem1 <- renderRHandsontable({
    rhandsontable(data$dfEBIT, colWidths = 150, height = 200, readOnly = TRUE, fixedColumnsLeft = 1, 
		manualColumnResize = TRUE, contextMenu = FALSE) |>
      hot_col(1, width = 450)
  })
  
  output$download_dfEBIT <- downloadHandler(
    filename = function() { "dfEBIT.xlsx" },
    content = function(file) { write.xlsx(data$dfEBIT, file) })

