`%||%` <- function(a, b) if (!is.null(a) && length(a) > 0) a else b

#EBT calculation

observe({
  req(data$dfEBIT, data$dfSumInterest, input$year_range, input$period)
  
  # Get period columns from existing structure
  period_cols <- names(data$dfGrossProfit)[-1]
  if(length(period_cols) == 0) return()
  
  # Initialize EBT with proper structure

  data$dfEBT <- data.table(
    Наименование = "ПРИБЫЛЬ ДО ВЫЧЕТА НАЛОГОВ (EBT)"
  )
  data$dfEBT[, (period_cols) := 0]
  
  # Calculate values with null coalescing

  for(col in period_cols) {
    if(col %in% names(data$dfEBIT) && col %in% names(data$dfSumInterest)) {
      EBIT <- data$dfEBIT[[col]][1] %||% 0
      SumInterest <- data$dfSumInterest[[col]][1] %||% 0
      data$dfEBT[, (col) := as.numeric(EBIT) - as.numeric(SumInterest)]
    }
  }
})

