#Net Income calculation

observe({
  req(data$dfEBT, data$dfSumTaxOnOperatingIncome, data$dfSumTaxOnNonOperatingIncome, input$year_range, input$period)
  
  # Get period columns from existing structure
  period_cols <- names(data$dfGrossProfit)[-1]
  if(length(period_cols) == 0) return()
  
  # Initialize Net Income with proper structure

  data$dfNetIncome <- data.table(
    Наименование = "ЧИСТАЯ ПРИБЫЛЬ (УБЫТОК)"
  )
  data$dfNetIncome[, (period_cols) := 0]
  
  # Calculate values with null coalescing

  for(col in period_cols) {
    if(col %in% names(data$dfEBT) && col %in% names(data$dfSumTaxOnOperatingIncome) && col %in% names(data$dfSumTaxOnNonOperatingIncome)) {
      EBT <- data$dfEBT[[col]][1] %||% 0
      SumTaxOnOperatingIncome <- data$dfSumTaxOnOperatingIncome[[col]][1] %||% 0
      SumTaxOnNonOperatingIncome <- data$dfSumTaxOnNonOperatingIncome[[col]][1] %||% 0
      data$dfNetIncome[, (col) := as.numeric(EBT) - as.numeric(SumTaxOnOperatingIncome) - as.numeric(SumTaxOnNonOperatingIncome)]
    }
  }
})

