# DFShareInLossInvestObject3 Calculation

observe({
  req(data$df7510, data$df7520, data$df7530, input$period, input$year_range)
  
  current_yr <- year(Sys.Date())
  selected_years <- switch(input$year_range,
    "Текущий год" = current_yr,
    "Предыдущий год" = current_yr - 1,
    "Позапрошлый год" = current_yr - 2,
    "Текущий и предыдущий годы" = c(current_yr, current_yr - 1),
    "Текущий, предыдущий и позапрошлый годы" = c(current_yr, current_yr - 1, current_yr - 2),
    "Предыдущий и позапрошлый годы" = c(current_yr - 1, current_yr - 2)
  )
  
  russian_months <- c("Январь", "Февраль", "Март", "Апрель", "Май", "Июнь",
                     "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь")
  
  period_info <- switch(input$period,
    "по месяцам" = list(labels = russian_months, count = 12, extract = function(d) month(d)),
    "по кварталам" = list(labels = paste0("Квартал ",1:4), count = 4, extract = quarter),
    "полугодовой" = list(labels = c("Первое полугодие","Второе полугодие"), count = 2, 
                        extract = function(d) ifelse(month(d) <= 6, 1, 2)),
    "годовой" = list(labels = "Годовой", count = 1, extract = function(d) 1)
  )
  
  all_cols <- unlist(lapply(selected_years, function(yr) 
    paste(period_info$labels[1:period_info$count], yr)))
  
  aggregate_debits <- function(dt) {
    res <- setNames(rep(0, length(all_cols)), all_cols)
    if (nrow(dt) == 0) return(res)
    
    dates <- as.Date(dt$`Дата учета`, format = "%Y-%m-%d")
    valid <- !is.na(dates) & year(dates) %in% selected_years
    if (!any(valid)) return(res)
    
    df <- data.table(
      y = year(dates[valid]),
      p = period_info$extract(dates[valid]),
      debit = dt$`Сумма доли убытка в прочем совокупном доходе объекта инвестиции за период`[valid]
    )[y %in% selected_years, .(s = sum(debit, na.rm = TRUE)), by = .(y, p)]
    
    for (i in 1:nrow(df)) {
      col <- paste(period_info$labels[df$p[i]], df$y[i])
      if (col %in% all_cols) res[col] <- df$s[i]
    }
    res
  }
  
  dfShareInLossInvestObject3 <- data$dfShareInLossInvestObject3
  if (nrow(dfShareInLossInvestObject3) == 0) return()
  
  df <- data.table(Наименование = as.character(dfShareInLossInvestObject3$Наименование))
  for (col in all_cols) df[, (col) := 0]
  
  for (i in 1:nrow(df)) {
    expense <- df$Наименование[i]
    if (is.na(expense)) next
    
    dt <- switch(expense,
		"7510.Доля в убытках материнской компании и компаний с совместным контролем или значительным влиянием" = data$df7510,
		"7520.Доля в убытках дочерних компаний и других организации той же группы" = data$df7520,
		"7530.Доля в убытках ассоциированных организаций и совместных предприятий" = data$df7530,
		NULL)
    
    if (is.null(dt)) next
    
    sum_debit <- aggregate_debits(dt)
    df[i, (all_cols) := as.list(sum_debit)]
  }
  data$dfShareInLossInvestObject3 <- df
})

