        dfSumTaxOnOCI_temp = as.data.table(data$dfSumTaxOnOCI),
        dfOCI_temp = as.data.table(data$dfOCI),
        dfTotalCI_temp = as.data.table(data$dfTotalCI))
    
    # Ensure all are data.tables and convert Наименование to character
    df_list <- lapply(df_list, function(df) {
        df$Наименование <- as.character(df$Наименование)
        df
    })
    
    # Collect all column names
    all_cols <- unique(unlist(lapply(df_list, names)))
    
    # Function to align columns
    align_columns <- function(dt) {
        missing_cols <- setdiff(all_cols, names(dt))
        if (length(missing_cols) > 0) {
            dt[, (missing_cols) := 0]
        }
        setcolorder(dt, all_cols)
        return(dt)
    }
    
    # Align all data frames
    df_list_aligned <- lapply(df_list, align_columns)
    
    # Combine into one data table
    dfCIReport_temp <- rbindlist(df_list_aligned, use.names = TRUE, fill = TRUE)
    
    # Update the reactive value
    data$dfCIReport <- dfCIReport_temp
})

