# Fixed observe block with safeguards

observe({
  req(data$df1010, data$df1020, data$df1030, data$df1040, data$df1050, data$df1070, data$df1080, input$period, input$year_range)
  
  current_yr <- year(Sys.Date())
  selected_years <- switch(input$year_range,
    "Текущий год" = current_yr,
    "Предыдущий год" = current_yr - 1,
    "Позапрошлый год" = current_yr - 2,
    "Текущий и предыдущий годы" = c(current_yr, current_yr - 1),
    "Текущий, предыдущий и позапрошлый годы" = c(current_yr, current_yr - 1, current_yr - 2),
    "Предыдущий и позапрошлый годы" = c(current_yr - 1, current_yr - 2),
    current_yr  # Default case
  )
  
  russian_months <- c("Январь", "Февраль", "Март", "Апрель", "Май", "Июнь",
                     "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь")
  
  period_info <- switch(input$period,
    "по месяцам" = list(labels = russian_months, count = 12, extract = function(d) month(d)),
    "по кварталам" = list(labels = paste0("Квартал ",1:4), count = 4, extract = quarter),
    "полугодовой" = list(labels = c("Первое полугодие","Второе полугодие"), count = 2, 
                        extract = function(d) ifelse(month(d) <= 6, 1, 2)),
    "годовой" = list(labels = "Годовой", count = 1, extract = function(d) 1),
    list(labels = "Годовой", count = 1, extract = function(d) 1)  # Default case
  )
  
  # Create column names

  all_cols <- unlist(lapply(selected_years, function(yr) 
    paste(period_info$labels[1:period_info$count], yr)))
  
  # Initialize Cash Flow Statement with columns

  cf_stmt <- data.table(Наименование = DFCashFlowStmt$Наименование)
  for (col in all_cols) {
    cf_stmt[, (col) := 0]
  }
    
  # Helper function to process transactions

 process_transactions <- function(dt, acct) {
  # Check if data exists
  if (is.null(dt) || nrow(dt) == 0) return(NULL)
  
  dt_filtered <- dt[
    (get(names(dt)[9]) == acct & get(names(dt)[10]) %in% AcctNumbersList3) |
    (get(names(dt)[10]) == acct & get(names(dt)[9]) %in% AcctNumbersList3) 
  ]
  
  if (nrow(dt_filtered) == 0) return(NULL)
  
  results <- data.table(
    row_index = integer(),
    period = integer(),
    year = integer(),
    amount = numeric()
  )
    
    # SAFE COLUMN ACCESS - CHECK LENGTH FIRST

    for (i in 1:nrow(dt_filtered)) {
      row <- dt_filtered[i, ]
      V3 <- as.character(row[["Назначение потока денежных средств"]])
      V9 <- as.character(row[["Счет № (дебет)"]])
      V10 <- as.character(row[["Счет № (кредит)"]])
      
      row_index_val <- NA_integer_
      amount_val <- 0
    
 # FIXED CONDITIONS WITH LENGTH CHECKS

if (!is.na(V9) && V9 == acct) {
  amount_val <- if ("Дебет" %in% names(row)) as.numeric(row[["Дебет"]]) else 0
  
  if (is.na(V3) || V3 == "Поступления от основной операционной деятельности") {
    row_index_val <- 1L
  } else if (V3 == "Поступления от прочей операционной деятельности") {
    row_index_val <- 2L
  } else if (V3 == "Поступления по процентам") {
    row_index_val <- 3L
  } else if (V3 == "Поступления по дивидендам") {
    row_index_val <- 4L
  } else if (V3 == "Поступления от реализации основных средств") {
    row_index_val <- 9L
  } else if (V3 == "Поступления от реализации нематериальных активов") {
    row_index_val <- 10L
  } else if (V3 == "Поступления от инвестиционного имущества") {
    row_index_val <- 11L
  } else if (V3 == "Поступления от реализации краткосрочных финансовых активов") {
    row_index_val <- 12L
  } else if (V3 == "Поступления от реализации долгосрочных финансовых активов") {
    row_index_val <- 13L
  } else if (V3 == "Отчуждение дочерних компаний") {
    row_index_val <- 14L
  } else if (V3 == "Прочие поступления по инвестиционной деятельности") {
    row_index_val <- 15L
  } else if (V3 == "Поступления от краткосрочных кредитов и займов") {
    row_index_val <- 24L
  } else if (V3 == "Поступления от долгосрочных кредитов и займов") {
    row_index_val <- 25L
  } else if (V3 == "Поступления по собственным долевым инструментам, в т.ч. казначейским") {
    row_index_val <- 26L
  } else if (V3 == "Поступления по собственным долговым инструментам") {
    row_index_val <- 27L
  } else if (V3 == "Поступления по деривативам, в т.ч. хеджируемым") {
    row_index_val <- 28L
  } else if (V3 == "Прочие поступления по финансовой деятельности") {
    row_index_val <- 29L
  }
} 
else if (!is.na(V10) && V10 == acct) {
  amount_val <- if ("Кредит" %in% names(row)) as.numeric(row[["Кредит"]]) else 0
  
  if (is.na(V3) || V3 == "Платежи по операционным расходам") {
    row_index_val <- 5L
  } else if (V3 == "Платежи по процентам") {
    row_index_val <- 6L
  } else if (V3 == "Платежи по налогам и сборам") {
    row_index_val <- 7L
  } else if (V3 == "Платежи на приобретение основных средств") {
    row_index_val <- 16L
  } else if (V3 == "Платежи на приобретение инвестиционного имущества") {
    row_index_val <- 17L
  } else if (V3 == "Платежи на приобретение нематериальных активов") {
    row_index_val <- 18L
  } else if (V3 == "Платежи на приобретение краткосрочных финансовых активов") {
    row_index_val <- 19L
  } else if (V3 == "Платежи на приобретение долгосрочных финансовых активов") {
    row_index_val <- 20L
  } else if (V3 == "Приобретение дочерних компаний, за вычетом их денежных средств") {
    row_index_val <- 21L
  } else if (V3 == "Прочие платежи по инвестиционной деятельности") {
    row_index_val <- 22L
  } else if (V3 == "Погашение краткосрочных кредитов и займов") {
    row_index_val <- 30L
  } else if (V3 == "Погашение долгосрочных кредитов и займов") {
    row_index_val <- 31L
  } else if (V3 == "Погашение обязательств по финансовой аренде") {
    row_index_val <- 32L
  } else if (V3 == "Платежи по деривативам, в т.ч. хеджируемым") {
    row_index_val <- 33L
  } else if (V3 == "Дивидендные платежи по долевым инструментам") {
    row_index_val <- 34L
  } else if (V3 == "Выкуп собственных долевых инструментов") {
    row_index_val <- 35L
  } else if (V3 == "Прочие платежи по финансовой деятельности") {
    row_index_val <- 36L
  }
}
    
    # Only process if we have valid values
    if (!is.na(row_index_val)) {
      date_val <- tryCatch(as.Date(row[[1]], format = "%Y-%m-%d"), error = function(e) NA)
      if (!is.na(date_val)) {
        yr <- lubridate::year(date_val)
        per <- period_info$extract(date_val)
        results <- rbind(results, list(row_index_val, per, yr, amount_val))
      }
    }
  }
  results
}
  # Process both data tables

	res1010 <- process_transactions(data$df1010, "1010")
	res1020 <- process_transactions(data$df1020, "1020")
	res1030 <- process_transactions(data$df1030, "1030")
	res1040 <- process_transactions(data$df1040, "1040")
	res1050 <- process_transactions(data$df1050, "1050")
	res1070 <- process_transactions(data$df1070, "1070")
	res1080 <- process_transactions(data$df1080, "1080")
	all_res <- rbind(res1010, res1020, res1030, res1040, res1050, res1070, res1080)
  
  # Aggregate results

  if (!is.null(all_res) && nrow(all_res) > 0) {
    agg_res <- all_res[, .(amount = sum(amount)), by = .(row_index, year, period)]
    
    # Apply to Cash Flow Statement

    for (i in 1:nrow(agg_res)) {
      r <- agg_res[i, ]
      col_name <- paste(period_info$labels[r$period], r$year)
      
      if (col_name %in% names(cf_stmt)) {
        current_val <- cf_stmt[r$row_index, get(col_name)]
        set(cf_stmt, i = r$row_index, j = col_name, value = current_val + r$amount)
      }
    }
  }
  
# Calculate rows 8, 23, 37 for each period column

  num_cols <- setdiff(names(cf_stmt), "Наименование")
  for (col in num_cols) {

    # row8 = (rows1_4) - (rows5_7)
    rows1_4 <- 1:4
    rows5_7 <- 5:7
    sum_inflows <- sum(cf_stmt[rows1_4, get(col)], na.rm = TRUE)
    sum_outflows <- sum(cf_stmt[rows5_7, get(col)], na.rm = TRUE)
    cf_stmt[8, (col) := sum_inflows - sum_outflows]
    
    # row23 = (rows9_15) - (rows16_22)
    rows9_15 <- 9:15
    rows16_22 <- 16:22
    sum_invest_inflows <- sum(cf_stmt[rows9_15, get(col)], na.rm = TRUE)
    sum_invest_outflows <- sum(cf_stmt[rows16_22, get(col)], na.rm = TRUE)
    cf_stmt[23, (col) := sum_invest_inflows - sum_invest_outflows]

    # row37 = (rows24_29) - (rows30_36)
    rows24_29 <- 24:29
    rows30_36 <- 30:36
    sum_finance_inflows <- sum(cf_stmt[rows24_29, get(col)], na.rm = TRUE)
    sum_finance_outflows <- sum(cf_stmt[rows30_36, get(col)], na.rm = TRUE)
    cf_stmt[37, (col) := sum_finance_inflows - sum_finance_outflows]
  }

  # Update reactive value

  data$dfCashFlowStmt <- cf_stmt
})

# Row 38 of dfCashFlowStmt calculation

observe({
  req(data$dfCashFlowStmt)
  current_cf <- data$dfCashFlowStmt
  
  # Get all period columns (exclude the first column "Наименование")
  num_cols <- setdiff(names(current_cf), "Наименование")
  if (length(num_cols) == 0) return()
  
  # Calculate new values for row 38
  new_row38_vals <- sapply(num_cols, function(col) {
    row8_val <- current_cf[8, get(col)]
    row23_val <- current_cf[23, get(col)]
    row37_val <- current_cf[37, get(col)]
    sum(c(row8_val, row23_val, row37_val), na.rm = TRUE)
  })
  
  # Update row 38 if values changed
  if (!identical(new_row38_vals, as.numeric(current_cf[38, ..num_cols]))) {
    new_cf <- copy(current_cf)
    new_cf[38, (num_cols) := as.list(new_row38_vals)]
    data$dfCashFlowStmt <- new_cf
  }
})

# New algorithm implementation

