  period2_info <- switch(input$period2,
    "по месяцам" = list(labels = russian_months, count = 12, extract = month),
    "по кварталам" = list(labels = paste0("Квартал ", 1:4), count = 4, extract = quarter),
    "полугодовой" = list(labels = c("Первое полугодие", "Второе полугодие"), count = 2, 
                        extract = function(d) ifelse(month(d) <= 6, 1, 2)),
    "годовой" = list(labels = "Годовой", count = 1, extract = function(d) 1),
    list(labels = "Годовой", count = 1, extract = function(d) 1)
  )
  
  # Create column names
  all_cols <- unlist(lapply(selected_years, function(yr) 
    paste(period2_info$labels[1:period2_info$count], yr)))
  
  # Account name mapping
  account_map <- AcctNamesMappingList2
  
  # Function to process transactions
  process_new_algorithm <- function(df, acct) {
    req_cols <- c("Дата операции", "Назначение потока денежных средств",
                  "Счет № (дебет)", 
                  "Счет № (кредит)", "Дебет", "Кредит")
    
    if (!all(req_cols %in% names(df))) {
      message("Missing required columns in dataframe")
      return(list())
