    for (i in 1:nrow(df)) {
      row <- df[i, ]
      if (all(is.na(row))) next
      
      # Robust date parsing
      date_val <- tryCatch(
        as.Date(row[["Дата операции"]], format = "%Y-%m-%d"),
        error = function(e) tryCatch(
          as.Date(row[["Дата операции"]], format = "%d.%m.%Y"),
          error = function(e) tryCatch(
            as.Date(row[["Дата операции"]], format = "%m/%d/%Y"),
            error = function(e) NA
          )
        )
      )
      
      if (is.na(date_val)) next
      
      # CORRECTED: Use column names instead of indices
      V3 <- tryCatch(as.character(row[["Назначение потока денежных средств"]]), error = function(e) "")
      V9 <- tryCatch(as.character(row[["Счет № (дебет)"]]), error = function(e) "")
      V10 <- tryCatch(as.character(row[["Счет № (кредит)"]]), error = function(e) "")
      
      debit_val <- tryCatch(as.numeric(gsub(",", ".", row[["Дебет"]])), 
                           warning = function(w) 0, error = function(e) 0)
      credit_val <- tryCatch(as.numeric(gsub(",", ".", row[["Кредит"]])), 
                            warning = function(w) 0, error = function(e) 0)
      
      yr_val <- year(date_val)
      if (!yr_val %in% selected_years) next
      
      per_val <- tryCatch(period2_info$extract(date_val), error = function(e) NA)
      if (is.na(per_val) || per_val < 1 || per_val > period2_info$count) next
      
      period_label <- paste(period2_info$labels[per_val], yr_val)
      
      for (cond in conditions) {
        # Check for matches with trimmed values
        if (!is.na(V3) && !is.na(V9) && !is.na(V10) &&
            trimws(V3) == cond$activity &&
            trimws(V9) %in% cond$debit_acct && 
            trimws(V10) %in% cond$credit_acct) {
          
          amount_val <- if (cond$amount_col == "Дебет") debit_val else credit_val
          account_val <- if (V9 %in% AcctNumbersList3) V9 else V10
          account_name <- if (account_val %in% names(account_map)) 
            account_map[account_val] else account_val
          
          results <- c(results, list(list(
            target = cond$target,
            account = account_name,
            amount = amount_val,
            period_label = period_label
          )))
        }
      }
    }
    return(results)
  }
  
  # Process transactions
 new_transactions <- c(
	process_new_algorithm(data$df1010, "1010"),
	process_new_algorithm(data$df1020, "1020"),
	process_new_algorithm(data$df1030, "1030"),
	process_new_algorithm(data$df1040, "1040"),
	process_new_algorithm(data$df1050, "1050"),
	process_new_algorithm(data$df1070, "1070"),
	process_new_algorithm(data$df1080, "1080")
	)
  
  # Initialize empty target tables
target_tables <- list(
    dfMainOperActivityProceeds = data.table(),
    dfOperActivityPayments = data.table(),
    dfOtherOperActivityProceeds = data.table(),
    dfSaleOfShortTermFinAssets = data.table(),
    dfAcquisitionOfShortTermFinAssets = data.table(),
    dfInterestProceeds = data.table(),
    dfDividendProceeds = data.table(),
    dfInterestPayments = data.table(),
    dfTaxPayments = data.table(),
    dfSaleOfTangibles = data.table(),
    dfSaleOfIntangibles = data.table(),
    dfInvestmentPropertyProceeds = data.table(),
    dfSaleOfLongTermFinAssets = data.table(),
    dfDisposalOfSubsidiaries = data.table(),
    dfOtherProceedsOfInvestActivity = data.table(),
    dfAcquisitionOfTangibles = data.table(),
    dfAcquisitionOfInvestmentProperty = data.table(),
    dfAcquisitionOfIntangibles = data.table(),
    dfAcquisitionOfLongTermFinAssets = data.table(),
    dfAcquisitionOfSubsidiaries = data.table(),
    dfOtherPaymentsOfInvestActivity = data.table(),
    dfProceedsOfShortTermBorrowings = data.table(),
    dfProceedsOfLongTermBorrowings = data.table(),
    dfProceedsOnOwnEquityInstruments = data.table(),
    dfProceedsOnOwnDebtInstruments = data.table(),
    dfProceedsOnDerivatives = data.table(),
    dfOtherProceedsOfFinActivity = data.table(),
    dfRepaymentOfShortTermBorrowings = data.table(),
    dfRepaymentOfLongTermBorrowings = data.table(),
    dfFinancialLeasePayments = data.table(),
    dfPaymentsOnDerivatives = data.table(),
    dfDividendPayments = data.table(),
    dfBuyoutOfOwnEquityInstruments = data.table(),
    dfOtherPaymentsOfFinActivity = data.table())
  
  # Process transactions if any exist
  if (length(new_transactions) > 0) {
    trans_dt <- rbindlist(new_transactions)
    
    # Create all target tables
    for (targ in names(target_tables)) {
      if (trans_dt[,.N] > 0) {
        # Filter and aggregate
        target_trans <- trans_dt[target == targ]
        if (nrow(target_trans) > 0) {
          agg_dt <- target_trans[, .(amount = sum(amount)), by = .(account, period_label)]
          target_tables[[targ]] <- dcast(agg_dt, account ~ period_label, 
                                        value.var = "amount", fill = 0)
        }
      }
    }
  }
  
  # Finalize target tables
  for (targ in names(target_tables)) {
    wide_dt <- target_tables[[targ]]
    
    # Create empty table if no transactions
    if (nrow(wide_dt) == 0) {
      wide_dt <- data.table(account = character())
    }
    
    # Rename and add columns
    if ("account" %in% names(wide_dt)) {
      setnames(wide_dt, "account", "Наименование")
    } else {
      wide_dt[, Наименование := character()]
    }
    
    # Add missing period columns
    missing_cols <- setdiff(all_cols, names(wide_dt))
    for (col in missing_cols) {
      wide_dt[, (col) := 0]
    }
    
    # Ensure correct column order
    setcolorder(wide_dt, c("Наименование", all_cols))
    
    # Update reactive values
    data[[targ]] <- wide_dt
  }
})

