req(data$dfBalanceSheet1,
    all(sapply(CashAccts_BSheet, function(x) !is.null(x))),
    all(sapply(ShortTermFinAssets1_BSheet, function(x) !is.null(x))),
    all(sapply(ShortTermFinAssets2_BSheet, function(x) !is.null(x))),
    all(sapply(ShortTermReceivables_BSheet, function(x) !is.null(x))),
    all(sapply(Inventory_BSheet, function(x) !is.null(x))),
    all(sapply(CurrentTaxAssets_BSheet, function(x) !is.null(x))),
    all(sapply(LongTermAssetsToAlienate_BSheet, function(x) !is.null(x))),
    all(sapply(ShortTermBioassets_BSheet, function(x) !is.null(x))),
    all(sapply(OtherShortTermAssets_BSheet, function(x) !is.null(x))),
    all(sapply(LongTermFinAssets_BSheet, function(x) !is.null(x))),
    all(sapply(LongTermReceivables_BSheet, function(x) !is.null(x))),
    all(sapply(Investments_BSheet, function(x) !is.null(x))),
    all(sapply(InvestmentProperty_BSheet, function(x) !is.null(x))),
    all(sapply(FixedAssets_BSheet, function(x) !is.null(x))),
    all(sapply(LongTermBioassets_BSheet, function(x) !is.null(x))),
    all(sapply(ExplorationEvaluationAssets_BSheet, function(x) !is.null(x))),
    all(sapply(Goodwill_BSheet, function(x) !is.null(x))),
    all(sapply(Intangibles_BSheet, function(x) !is.null(x))),
    all(sapply(DeferredTaxAssets_BSheet, function(x) !is.null(x))),
    all(sapply(OtherLongTermAssets_BSheet, function(x) !is.null(x))),
    all(sapply(ShortTermFinLiabilities_BSheet, function(x) !is.null(x))),
    all(sapply(CurrentTaxLiabilities_BSheet, function(x) !is.null(x))),
    all(sapply(OtherDues_BSheet, function(x) !is.null(x))),
    all(sapply(ShortTermPayables_BSheet, function(x) !is.null(x))),
    all(sapply(ShortTermProvisions_BSheet, function(x) !is.null(x))),
    all(sapply(OtherShortTermLiabilities_BSheet, function(x) !is.null(x))),
    all(sapply(LongTermFinLiabilities_BSheet, function(x) !is.null(x))),
    all(sapply(LongTermPayables_BSheet, function(x) !is.null(x))),
    all(sapply(LongTermProvisions_BSheet, function(x) !is.null(x))),
    all(sapply(DeferredTaxLiabilities_BSheet, function(x) !is.null(x))),
    all(sapply(OtherLongTermLiabilities_BSheet, function(x) !is.null(x))),
    all(sapply(Capital_BSheet, function(x) !is.null(x))),
    all(sapply(UnpaidCapital_BSheet, function(x) !is.null(x))),
    all(sapply(TreasuryShares_BSheet, function(x) !is.null(x))),
    all(sapply(SharePremium_BSheet, function(x) !is.null(x))),
    all(sapply(AdditionalPaidInCapital_BSheet, function(x) !is.null(x))),
    all(sapply(Provisions_BSheet, function(x) !is.null(x))),
    all(sapply(RetainedEarningsUncoveredLoss_BSheet, function(x) !is.null(x))),
    input$periodBS1, input$year_rangeBS1)

  current_yr <- year(Sys.Date())
  selected_years <- switch(input$year_rangeBS1,
    "Текущий год" = current_yr,
    "Предыдущий год" = current_yr - 1,
    "Позапрошлый год" = current_yr - 2,
    current_yr
  )
  
  russian_months <- c("Январь", "Февраль", "Март", "Апрель", "Май", "Июнь",
                      "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь")
  
  periodBS1_info <- switch(input$periodBS1,
    "по месяцам" = list(labels = russian_months, count = 12, extract = month),
    "по кварталам" = list(labels = paste0("Квартал ", 1:4), count = 4, extract = quarter),
    "полугодовой" = list(labels = c("Первое полугодие", "Второе полугодие"), count = 2, 
                       extract = function(d) ifelse(month(d) <= 6, 1, 2)),
    "годовой" = list(labels = "Годовой", count = 1, extract = function(d) 1),
    list(labels = "Годовой", count = 1, extract = function(d) 1)
  )
  
  # Create column names for the selected year
  all_cols <- paste(periodBS1_info$labels[1:periodBS1_info$count], selected_years)
  
  # Initialize periodBS1 columns if they don't exist
  bs <- copy(data$dfBalanceSheet1)
  for(col in all_cols) {
    if(!col %in% names(bs)) bs[, (col) := as.numeric(0)]
  }
  
  # Remove old periodBS1 columns not in current selection
  old_cols <- setdiff(names(bs), c("Наименование", "Начальное сальдо", all_cols))
  if(length(old_cols) > 0) bs[, (old_cols) := NULL]
  
  # Determine current period index if current year
  if(input$year_rangeBS1 == "Текущий год") {
    current_period_idx <- switch(input$periodBS1,
      "по месяцам" = month(Sys.Date()),
      "по кварталам" = quarter(Sys.Date()),
      "полугодовой" = ifelse(month(Sys.Date()) <= 6, 1, 2),
      1  # Default for annual
    )
  } else {
    current_period_idx <- Inf  # No future periods in non-current years
  }
  
  # Helper function to safely sum net values (debit - credit) with date filtering
  safe_sum_net <- function(df, start, end) {
    if(nrow(df) == 0) return(0)
    # Always limit end date to Sys.Date() to exclude future transactions
    actual_end <- min(end, Sys.Date())
    df_sub <- df[as.Date(`Дата операции`) >= start & as.Date(`Дата операции`) <= actual_end]
    if(nrow(df_sub) > 0) {
      sum(df_sub$Дебет, na.rm = TRUE) - sum(df_sub$Кредит, na.rm = TRUE)
    } else 0
  }
  
  # Process each periodBS1 in chronological order
  yr <- selected_years
  for(periodBS1_idx in 1:periodBS1_info$count) {
    col_name <- paste(periodBS1_info$labels[periodBS1_idx], yr)
    
    # Determine previous column for cumulative calculation
    prev_col <- if(periodBS1_idx == 1) {
      "Начальное сальдо"
    } else {
      paste(periodBS1_info$labels[periodBS1_idx - 1], yr)
    }
    
    # Define date range for current periodBS1
    periodBS1_start <- if(periodBS1_info$count == 1) {
      ymd(paste0(yr, "-01-01"))
    } else if(periodBS1_info$count == 2) {
      if(periodBS1_idx == 1) ymd(paste0(yr, "-01-01")) else ymd(paste0(yr, "-07-01"))
    } else if(periodBS1_info$count == 4) {
      start_months <- c(1, 4, 7, 10)
      ymd(paste0(yr, "-", start_months[periodBS1_idx], "-01"))
    } else {
      ymd(paste0(yr, "-", periodBS1_idx, "-01"))
    }
    
    periodBS1_end <- if(periodBS1_info$count == 1) {
      ymd(paste0(yr, "-12-31"))
    } else if(periodBS1_info$count == 2) {
      if(periodBS1_idx == 1) ymd(paste0(yr, "-06-30")) else ymd(paste0(yr, "-12-31"))
    } else if(periodBS1_info$count == 4) {
      end_months <- c(3, 6, 9, 12)
      ymd(paste0(yr, "-", end_months[periodBS1_idx], "-", days_in_month(end_months[periodBS1_idx])))
    } else {
      ymd(paste0(yr, "-", periodBS1_idx, "-", days_in_month(periodBS1_idx)))
    }
    
    # Calculate for each row
    for(i in 1:nrow(bs)) {
      base <- if(prev_col %in% names(bs)) bs[[prev_col]][i] else 0
      
      # Condition 2 & 3: Skip future periods for specific rows in current year
      if(input$year_rangeBS1 == "Текущий год" && periodBS1_idx > current_period_idx) {
        if(i %in% 1:3) {
          bs[i, (col_name) := 0]
          next
        }
      }
      
#****************************
#КРАТКОСРОЧНЫЕ АКТИВЫ

      if(i == 1) { #Денежные средства и их эквиваленты
       CashAccts_net <- 0
        for(account in names(CashAccts_BSheet)) {
         CashAccts_net <-CashAccts_net + safe_sum_net(CashAccts_BSheet[[account]], periodBS1_start, periodBS1_end)
        }        
        # Process financial asset accounts for cash equivalents
        ShortTermFinAssets_net1 <- 0
        for(account in names(ShortTermFinAssets1_BSheet)) {
          df <- ShortTermFinAssets1_BSheet[[account]]
          df_cond <- df[
            `Срок погашения с даты приобретения (в кол-ве месяцев)` <= 3 & 
            `Степень риска (кредитного, рыночного или др.)` == "незначительная"
          ]
          ShortTermFinAssets_net1 <- ShortTermFinAssets_net1 + safe_sum_net(df_cond, periodBS1_start, periodBS1_end)
        }      
        bs[i, (col_name) := base +CashAccts_net + ShortTermFinAssets_net1]
      }

      else if(i == 2) { #Краткосрочные финансовые активы
        ShortTermFinAssets_net1 <- 0
        for(account in names(ShortTermFinAssets1_BSheet)) {
          df <- ShortTermFinAssets1_BSheet[[account]]
          df_cond <- df[
            `Срок погашения с даты приобретения (в кол-ве месяцев)` > 3 | 
            `Степень риска (кредитного, рыночного или др.)` != "незначительная"
          ]
          ShortTermFinAssets_net1 <- ShortTermFinAssets_net1 + safe_sum_net(df_cond, periodBS1_start, periodBS1_end)
      }
        ShortTermFinAssets_net2 <- 0
        for(account in names(ShortTermFinAssets2_BSheet)) {
          ShortTermFinAssets_net2 <- ShortTermFinAssets_net2 + safe_sum_net(ShortTermFinAssets2_BSheet[[account]], periodBS1_start, periodBS1_end)
        }    
        bs[i, (col_name) := base + ShortTermFinAssets_net1 + ShortTermFinAssets_net2]
      }

      else if(i == 3) { #Краткосрочная дебиторская задолженность
        ShortTermReceivables_net <- 0
        for(account in names(ShortTermReceivables_BSheet)) {
          ShortTermReceivables_net <- ShortTermReceivables_net + safe_sum_net(ShortTermReceivables_BSheet[[account]], periodBS1_start, periodBS1_end)
        }
        bs[i, (col_name) := base + ShortTermReceivables_net]
      }

      else if(i == 4) { #Запасы
